function safeAddColumn(tableName, columnName, columnDef) {
  try {
    const tableInfo = db.prepare(`PRAGMA table_info(${tableName})`).all();
    const exists = tableInfo.some((col) => col.name === columnName);
    if (!exists) {
      db.prepare(`ALTER TABLE ${tableName} ADD COLUMN ${columnName} ${columnDef}`).run();
    }
  } catch {
  }
}
function normalizeSuggestion(row) {
  if (!row) return row;
  const normalized = { ...row };
  normalized.suggestion = row.suggestion || row.content || "";
  normalized.content = row.content || row.suggestion || "";
  normalized.user_tag = row.user_tag || row.user_id || "";
  normalized.status = row.status === "pending" || !row.status ? "beklemede" : row.status;
  normalized.upvoted_by = row.upvoted_by || "[]";
  normalized.downvoted_by = row.downvoted_by || "[]";
  normalized.voters = row.voters || "{}";
  normalized.created_at = row.created_at || (/* @__PURE__ */ new Date()).toISOString();
  normalized.updated_at = row.updated_at || normalized.created_at;
  return normalized;
}
function backupDatabase() {
  let tempPath = "";
  try {
    if (process.env.ENABLE_DB_BACKUP !== "true") {
      return { success: false, error: "Manual backup is disabled in single-file database mode." };
    }
    const dateStr = (/* @__PURE__ */ new Date()).toISOString().replace(/[:.]/g, "-").slice(0, 19);
    const backupFileName = `vega_${dateStr}.sqlite`;
    const targetPath = path.join(backupDir, backupFileName);
    tempPath = `${targetPath}.tmp`;
    if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath);
    db.exec(`VACUUM INTO '${tempPath.replace(/'/g, "''")}'`);
    const snapshot = new Database(tempPath, { readonly: true });
    try {
      const check = snapshot.pragma("quick_check");
      if (check.length && Object.values(check[0])[0] !== "ok") {
        throw new Error("SQLite yede\u011Fi b\xFCt\xFCnl\xFCk kontrol\xFCnden ge\xE7emedi");
      }
    } finally {
      snapshot.close();
    }
    fs.renameSync(tempPath, targetPath);
    tempPath = "";
    logger.success(`Veritaban\u0131 yede\u011Fi olu\u015Fturuldu: ${backupFileName}`, "Backup");
    return { success: true, file: backupFileName };
  } catch (error) {
    if (tempPath && fs.existsSync(tempPath)) {
      try {
        fs.unlinkSync(tempPath);
      } catch {
      }
    }
    logger.error("Veritaban\u0131 yedeklenirken hata olu\u015Ftu", error, "Backup");
    return { success: false, error: error?.message || "Bilinmeyen hata" };
  }
}
