  // KÜRESEL AFK SİSTEMİ (Global AFK - Faz 8 Onarımı)
  setAfk(userId, reason, guildId) {
    const now = Date.now();
    db.prepare(`
      INSERT INTO afk (user_id, reason, since, guild_id)
      VALUES (?, ?, ?, ?)
      ON CONFLICT(user_id) DO UPDATE SET reason = ?, since = ?, guild_id = ?
    `).run(userId, reason, now, guildId || null, reason, now, guildId || null);
    try {
      db.prepare(`
        UPDATE users SET afk = 1, afk_reason = ?, afk_since = ? WHERE id = ?
      `).run(reason, now, userId);
    } catch {
    }
  },
  removeAfk(userId) {
    const stmt = db.prepare("SELECT * FROM afk WHERE user_id = ?");
    const existing = stmt.get(userId);
    if (existing) {
      db.prepare("DELETE FROM afk WHERE user_id = ?").run(userId);
    }
    try {
      db.prepare("UPDATE users SET afk = 0, afk_reason = NULL, afk_since = NULL WHERE id = ?").run(userId);
    } catch {
    }
    return existing || null;
  },
  getAfk(userId, _guildId) {
    const stmt = db.prepare("SELECT * FROM afk WHERE user_id = ?");
    const row = stmt.get(userId);
    if (row) return row;
    try {
      const userRow = db.prepare("SELECT afk, afk_reason, afk_since, guild_id FROM users WHERE id = ? AND afk = 1").get(userId);
      if (userRow && userRow.afk === 1) {
        return {
          user_id: userId,
          reason: userRow.afk_reason || "Belirtilmedi",
          since: userRow.afk_since || Date.now(),
          guild_id: userRow.guild_id || _guildId || null
        };
      }
    } catch {
    }
    return null;
  },
