  voteSuggestion(suggestionId, userId, voteType) {
    const row = db.prepare("SELECT * FROM suggestions WHERE id = ?").get(suggestionId);
    if (!row) return null;
    let voters = {};
    try {
      voters = JSON.parse(row.voters || "{}");
    } catch {
      voters = {};
    }
    const previousVote = voters[userId];
    if (previousVote === voteType) {
      delete voters[userId];
    } else {
      voters[userId] = voteType;
    }
    let upCount = 0;
    let downCount = 0;
    Object.values(voters).forEach((v) => {
      if (v === "up") upCount++;
      if (v === "down") downCount++;
    });
    db.prepare("UPDATE suggestions SET upvotes = ?, downvotes = ?, voters = ? WHERE id = ?").run(
      upCount,
      downCount,
      JSON.stringify(voters),
      suggestionId
    );
    return { upvotes: upCount, downvotes: downCount, changed: true };
  },
