  // Sanal Evlilik & Aşk Sistemi (1. Eş, 2. Eş, 3. Eş Desteği)
  getMarriages(guildId, userId) {
    try {
      const rows = db.prepare(`
        SELECT * FROM marriages 
        WHERE guild_id = ? AND (user1_id = ? OR user2_id = ?)
        ORDER BY id ASC
      `).all(guildId, userId, userId);
      return rows || [];
    } catch {
      return [];
    }
  },
  getMarriage(guildId, userId, targetSpouseIdOrSlot) {
    try {
      const all = this.getMarriages(guildId, userId);
      if (all.length === 0) return null;
      if (typeof targetSpouseIdOrSlot === "number") {
        const bySlot = all.find((m) => {
          if (m.user1_id === userId) return m.user1_slot === targetSpouseIdOrSlot;
          return m.user2_slot === targetSpouseIdOrSlot;
        });
        return bySlot || all[targetSpouseIdOrSlot - 1] || null;
      }
      if (typeof targetSpouseIdOrSlot === "string" && targetSpouseIdOrSlot.trim().length > 0) {
        const found = all.find((m) => m.user1_id === targetSpouseIdOrSlot || m.user2_id === targetSpouseIdOrSlot);
        if (found) return found;
      }
      return all[0] || null;
    } catch {
      return null;
    }
  },
  createMarriage(guildId, user1Id, user2Id, ringType = "\u{1F48D} Alt\u0131n P\u0131rlanta Y\xFCz\xFCk", user1Slot = 1, user2Slot = 1) {
    try {
      db.prepare(`
        INSERT INTO marriages (guild_id, user1_id, user2_id, ring_type, love_points, married_at, user1_slot, user2_slot)
        VALUES (?, ?, ?, ?, 100, ?, ?, ?)
      `).run(guildId, user1Id, user2Id, ringType, Date.now(), user1Slot, user2Slot);
      return true;
    } catch {
      try {
        db.prepare(`
          INSERT INTO marriages (guild_id, user1_id, user2_id, ring_type, love_points, married_at)
          VALUES (?, ?, ?, ?, 100, ?)
        `).run(guildId, user1Id, user2Id, ringType, Date.now());
        return true;
      } catch {
        return false;
      }
    }
  },
  deleteMarriage(guildId, userId, targetSpouseId) {
    try {
      if (targetSpouseId) {
        const res2 = db.prepare(`
          DELETE FROM marriages 
          WHERE guild_id = ? AND (
            (user1_id = ? AND user2_id = ?) OR 
            (user1_id = ? AND user2_id = ?)
          )
        `).run(guildId, userId, targetSpouseId, targetSpouseId, userId);
        return res2.changes > 0;
      }
      const all = this.getMarriages(guildId, userId);
      if (all.length === 0) return false;
      const res = db.prepare("DELETE FROM marriages WHERE id = ?").run(all[0].id);
      return res.changes > 0;
    } catch {
      return false;
    }
  },
  deleteMarriageById(id) {
    try {
      const res = db.prepare("DELETE FROM marriages WHERE id = ?").run(id);
      return res.changes > 0;
    } catch {
      return false;
    }
  },
  addLovePoints(guildId, userId, points, targetSpouseId) {
    const marriage = targetSpouseId ? this.getMarriage(guildId, userId, targetSpouseId) : this.getMarriage(guildId, userId);
    if (!marriage) return 0;
    const newPoints = Math.max(0, marriage.love_points + points);
    try {
      db.prepare("UPDATE marriages SET love_points = ? WHERE id = ?").run(newPoints, marriage.id);
      return newPoints;
    } catch {
      return marriage.love_points;
    }
  },
  // İtibar & Saygı (Reputation)
  addRep(guildId, targetUserId, fromUserId) {
    const fromUser = this.getUser(fromUserId, guildId);
    const now = Date.now();
    const cooldownMs = 24 * 60 * 60 * 1e3;
    const lastRep = fromUser.last_rep || 0;
    if (now - lastRep < cooldownMs) {
      return { success: false, cooldownLeft: Math.ceil((cooldownMs - (now - lastRep)) / (60 * 60 * 1e3)) };
    }
    const targetUser = this.getUser(targetUserId, guildId);
    const newRep = (targetUser.rep || 0) + 1;
    this.updateUser(targetUserId, guildId, { rep: newRep });
    this.updateUser(fromUserId, guildId, { last_rep: now });
    return { success: true, newRep };
  },
