  // Faz 14: Detaylı Kullanıcı Yönetimi (Panel İçin)
  getAllUsersList(options) {
    const limit = options?.limit || 50;
    const offset = options?.offset || 0;
    const search = options?.search ? `%${options.search}%` : null;
    const guildId = options?.guildId || null;
    try {
      let countQuery = "SELECT COUNT(*) as count FROM users WHERE 1=1";
      let dataQuery = "SELECT * FROM users WHERE 1=1";
      const params = [];
      if (guildId) {
        countQuery += " AND guild_id = ?";
        dataQuery += " AND guild_id = ?";
        params.push(guildId);
      }
      if (search) {
        countQuery += " AND id LIKE ?";
        dataQuery += " AND id LIKE ?";
        params.push(search);
      }
      const total = db.prepare(countQuery).get(...params)?.count || 0;
      dataQuery += " ORDER BY level DESC, xp DESC LIMIT ? OFFSET ?";
      const users = db.prepare(dataQuery).all(...params, limit, offset);
      return { users, total };
    } catch {
      return { users: [], total: 0 };
    }
  },
  updateUserStats(userId, guildId, data) {
    try {
      this.updateUser(userId, guildId, data);
      return true;
    } catch {
      return false;
    }
  },
  // Faz 14: Veritabanı Tabloları Gezgini (Database Browser)
  getAllTableNames() {
    try {
      const rows = db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name ASC").all();
      return rows.map((r) => r.name);
    } catch {
      return [];
    }
  },
  getTableRows(tableName, options) {
    const requestedLimit = Number(options?.limit ?? 25);
    const requestedOffset = Number(options?.offset ?? 0);
    const limit = Number.isFinite(requestedLimit) ? Math.min(100, Math.max(1, Math.floor(requestedLimit))) : 25;
    const offset = Number.isFinite(requestedOffset) ? Math.max(0, Math.floor(requestedOffset)) : 0;
    const validTables = this.getAllTableNames();
    if (!validTables.includes(tableName)) {
      return { rows: [], total: 0, columns: [] };
    }
    try {
      const colInfo = getTableInfo(tableName);
      const columns = colInfo.map((c) => c.name);
      const quotedTable = quoteIdentifier(tableName);
      const total = db.prepare(`SELECT COUNT(*) as count FROM ${quotedTable}`).get()?.count || 0;
      const rows = db.prepare(`SELECT * FROM ${quotedTable} LIMIT ? OFFSET ?`).all(limit, offset);
      return { rows, total, columns };
    } catch {
      return { rows: [], total: 0, columns: [] };
    }
  },
  updateTableRow(tableName, pkColumn, pkValue, updates) {
    const validTables = this.getAllTableNames();
    if (!validTables.includes(tableName)) return false;
    try {
      if (!updates || typeof updates !== "object" || Array.isArray(updates)) return false;
      const columns = getTableInfo(tableName);
      const primaryKeys = columns.filter((column) => column.pk > 0);
      if (primaryKeys.length !== 1 || primaryKeys[0].name !== pkColumn) return false;
      const validColumns = new Set(columns.map((column) => column.name));
      const keys = Object.keys(updates).filter((k) => k !== pkColumn);
      if (keys.length === 0 || keys.some((key) => !validColumns.has(key))) return false;
      const setClauses = keys.map((k) => `${quoteIdentifier(k)} = ?`).join(", ");
      const values = keys.map((k) => updates[k]);
      const res = db.prepare(`UPDATE ${quoteIdentifier(tableName)} SET ${setClauses} WHERE ${quoteIdentifier(pkColumn)} = ?`).run(...values, pkValue);
      return res.changes > 0;
    } catch {
      return false;
    }
  },
  deleteTableRow(tableName, pkColumn, pkValue) {
    const validTables = this.getAllTableNames();
    if (!validTables.includes(tableName)) return false;
    try {
      const columns = getTableInfo(tableName);
      const primaryKeys = columns.filter((column) => column.pk > 0);
      if (primaryKeys.length !== 1 || primaryKeys[0].name !== pkColumn) return false;
      const res = db.prepare(`DELETE FROM ${quoteIdentifier(tableName)} WHERE ${quoteIdentifier(pkColumn)} = ?`).run(pkValue);
      return res.changes > 0;
    } catch {
      return false;
    }
  },
