  getGameLeaderboard(guildId, gameType, limit = 10) {
    try {
      let rows;
      if (gameType) {
        rows = db.prepare(`
          SELECT user_id, score, game_type 
          FROM game_scores 
          WHERE guild_id = ? AND game_type = ? 
          ORDER BY score DESC 
          LIMIT ?
        `).all(guildId, gameType, limit);
      } else {
        rows = db.prepare(`
          SELECT user_id, SUM(score) as score, 'genel' as game_type 
          FROM game_scores 
          WHERE guild_id = ? 
          GROUP BY user_id 
          ORDER BY score DESC 
          LIMIT ?
        `).all(guildId, limit);
      }
      return rows.map((r, idx) => ({ ...r, rank: idx + 1 }));
    } catch {
      return [];
    }
  },
