  // FAZ 16 / BÜYÜK GÜNCELLEME: ENVANTER (RPG BALIK & MADENCİLİK) & STARBOARD
  // =========================================================================
  addInventoryItem(userId, guildId, itemId, itemName, quantity = 1, category = "genel") {
    try {
      const existing = db.prepare("SELECT * FROM inventory WHERE user_id = ? AND guild_id = ? AND item_id = ?").get(userId, guildId, itemId);
      if (existing) {
        db.prepare("UPDATE inventory SET quantity = quantity + ?, updated_at = CURRENT_TIMESTAMP WHERE user_id = ? AND guild_id = ? AND item_id = ?").run(quantity, userId, guildId, itemId);
      } else {
        db.prepare("INSERT INTO inventory (user_id, guild_id, item_id, item_name, quantity, category) VALUES (?, ?, ?, ?, ?, ?)").run(userId, guildId, itemId, itemName, quantity, category);
      }
    } catch (err) {
      logger.error("addInventoryItem hatas\u0131", err, "Database");
    }
  },
  getUserInventory(userId, guildId) {
    try {
      return db.prepare("SELECT * FROM inventory WHERE user_id = ? AND guild_id = ? AND quantity > 0 ORDER BY category ASC, quantity DESC").all(userId, guildId);
    } catch {
      return [];
    }
  },
  removeInventoryItem(userId, guildId, itemId, quantity = 1) {
    try {
      const existing = db.prepare("SELECT * FROM inventory WHERE user_id = ? AND guild_id = ? AND item_id = ?").get(userId, guildId, itemId);
      if (!existing || existing.quantity < quantity) {
        return false;
      }
      if (existing.quantity === quantity) {
        db.prepare("DELETE FROM inventory WHERE user_id = ? AND guild_id = ? AND item_id = ?").run(userId, guildId, itemId);
      } else {
        db.prepare("UPDATE inventory SET quantity = quantity - ?, updated_at = CURRENT_TIMESTAMP WHERE user_id = ? AND guild_id = ? AND item_id = ?").run(quantity, userId, guildId, itemId);
      }
      return true;
    } catch (err) {
      logger.error("removeInventoryItem hatas\u0131", err, "Database");
      return false;
    }
  },
