  createSuggestion(guildId, userId, userTag, suggestion, channelId, messageId) {
    try {
      const info = db.prepare(`
        INSERT INTO suggestions (guild_id, user_id, user_tag, content, suggestion, status, channel_id, message_id)
        VALUES (?, ?, ?, ?, ?, 'beklemede', ?, ?)
      `).run(guildId, userId, userTag, suggestion, suggestion, channelId || null, messageId || null);
      return Number(info.lastInsertRowid);
    } catch (err) {
      logger.error("createSuggestion hatas\u0131", err, "Database");
      return 0;
    }
  },
  getSuggestion(id) {
    try {
      const row = db.prepare("SELECT * FROM suggestions WHERE id = ?").get(id);
      return normalizeSuggestion(row);
    } catch {
      return null;
    }
  },
  getGuildSuggestions(guildId, status) {
    try {
      let rows;
      if (status) {
        rows = db.prepare("SELECT * FROM suggestions WHERE guild_id = ? AND status = ? ORDER BY id DESC").all(guildId, status);
      } else {
        rows = db.prepare("SELECT * FROM suggestions WHERE guild_id = ? ORDER BY id DESC").all(guildId);
      }
      return rows.map(normalizeSuggestion);
    } catch {
      return [];
    }
  },
  updateSuggestionStatus(id, status, adminResponse, adminId) {
    try {
      db.prepare(`
        UPDATE suggestions 
        SET status = ?, admin_response = ?, admin_id = ?, updated_at = CURRENT_TIMESTAMP
        WHERE id = ?
      `).run(status, adminResponse || null, adminId || null, id);
      return true;
    } catch (err) {
      logger.error("updateSuggestionStatus hatas\u0131", err, "Database");
      return false;
    }
  },
  voteSuggestionDetailed(id, userId, voteType) {
    try {
      const row = db.prepare("SELECT * FROM suggestions WHERE id = ?").get(id);
      if (!row) return null;
      let upvotedBy = [];
      let downvotedBy = [];
      try {
        upvotedBy = JSON.parse(row.upvoted_by || "[]");
      } catch {
      }
      try {
        downvotedBy = JSON.parse(row.downvoted_by || "[]");
      } catch {
      }
      const hasUpvoted = upvotedBy.includes(userId);
      const hasDownvoted = downvotedBy.includes(userId);
      let userVote = "none";
      if (voteType === "up") {
        if (hasUpvoted) {
          upvotedBy = upvotedBy.filter((u) => u !== userId);
          userVote = "none";
        } else {
          upvotedBy.push(userId);
          downvotedBy = downvotedBy.filter((u) => u !== userId);
          userVote = "up";
        }
      } else {
        if (hasDownvoted) {
          downvotedBy = downvotedBy.filter((u) => u !== userId);
          userVote = "none";
        } else {
          downvotedBy.push(userId);
          upvotedBy = upvotedBy.filter((u) => u !== userId);
          userVote = "down";
        }
      }
      const upvotes = upvotedBy.length;
      const downvotes = downvotedBy.length;
      db.prepare(`
        UPDATE suggestions
        SET upvotes = ?, downvotes = ?, upvoted_by = ?, downvoted_by = ?, updated_at = CURRENT_TIMESTAMP
        WHERE id = ?
      `).run(upvotes, downvotes, JSON.stringify(upvotedBy), JSON.stringify(downvotedBy), id);
      return { upvotes, downvotes, userVote };
    } catch (err) {
      logger.error("voteSuggestionDetailed hatas\u0131", err, "Database");
      return null;
    }
  },
