  deleteCaptchaSettings(guildId) {
    try {
      db.prepare("DELETE FROM captcha_settings WHERE guild_id = ?").run(guildId);
    } catch {
    }
  },
  setCaptchaSession(guildId, userId, code, expiresAt) {
    try {
      db.prepare(`
        INSERT INTO captcha_sessions (guild_id, user_id, code, attempts, expires_at, locked_until)
        VALUES (?, ?, ?, 0, ?, 0)
        ON CONFLICT(guild_id, user_id) DO UPDATE SET
          code = excluded.code,
          attempts = 0,
          expires_at = excluded.expires_at,
          locked_until = 0
      `).run(guildId, userId, code, expiresAt);
    } catch {
    }
  },
  getCaptchaSession(guildId, userId) {
    try {
      return db.prepare("SELECT * FROM captcha_sessions WHERE guild_id = ? AND user_id = ?").get(guildId, userId);
    } catch {
      return null;
    }
  },
  incrementCaptchaAttempts(guildId, userId, lockDurationMs = 3e5) {
    try {
      const session = this.getCaptchaSession(guildId, userId);
      if (!session) return { attempts: 1, isLocked: false };
      const nextAttempts = (session.attempts || 0) + 1;
      let lockedUntil = session.locked_until || 0;
      if (nextAttempts >= 3) {
        lockedUntil = Date.now() + lockDurationMs;
      }
      db.prepare(`
        UPDATE captcha_sessions 
        SET attempts = ?, locked_until = ?
        WHERE guild_id = ? AND user_id = ?
      `).run(nextAttempts, lockedUntil, guildId, userId);
      return {
        attempts: nextAttempts,
        isLocked: nextAttempts >= 3
      };
    } catch {
      return { attempts: 1, isLocked: false };
    }
  },
  removeCaptchaSession(guildId, userId) {
    try {
      db.prepare("DELETE FROM captcha_sessions WHERE guild_id = ? AND user_id = ?").run(guildId, userId);
    } catch {
    }
  },
