  // FAZ 16C2: ETKİNLİKLER (EVENTS)
  // ==========================================
  createEvent(guildId, name, date, time, description, createdBy) {
    try {
      const res = db.prepare(`
        INSERT INTO events (guild_id, name, date, time, description, created_by, participants)
        VALUES (?, ?, ?, ?, ?, ?, '[]')
      `).run(guildId, name, date, time, description, createdBy);
      return { id: Number(res.lastInsertRowid) };
    } catch {
      return { id: 0 };
    }
  },
  getEvents(guildId) {
    try {
      const rows = db.prepare("SELECT * FROM events WHERE guild_id = ? ORDER BY id DESC").all(guildId);
      return rows.map((r) => ({
        ...r,
        participants: typeof r.participants === "string" ? JSON.parse(r.participants) : r.participants
      }));
    } catch {
      return [];
    }
  },
  getEventById(eventId) {
    try {
      const r = db.prepare("SELECT * FROM events WHERE id = ?").get(eventId);
      if (!r) return null;
      return {
        ...r,
        participants: typeof r.participants === "string" ? JSON.parse(r.participants) : r.participants
      };
    } catch {
      return null;
    }
  },
  deleteEvent(guildId, eventId) {
    try {
      const res = db.prepare("DELETE FROM events WHERE guild_id = ? AND id = ?").run(guildId, eventId);
      return res.changes > 0;
    } catch {
      return false;
    }
  },
  toggleEventParticipation(eventId, userId) {
    try {
      const ev = this.getEventById(eventId);
      if (!ev) return { joined: false, count: 0 };
      let list = ev.participants || [];
      let joined = false;
      if (list.includes(userId)) {
        list = list.filter((id) => id !== userId);
        joined = false;
      } else {
        list.push(userId);
        joined = true;
      }
      db.prepare("UPDATE events SET participants = ? WHERE id = ?").run(JSON.stringify(list), eventId);
      return { joined, count: list.length };
    } catch {
      return { joined: false, count: 0 };
    }
  },
