function shortTitle(title) {
  return title.replace(/\bII\b/gi, "").replace(/[⟦⟧]/g, "").replace(/\s+/g, " ").trim().slice(0, 80);
}
function requesterTime() {
  const parts = new Intl.DateTimeFormat("tr-TR", {
    timeZone: "Europe/Istanbul",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false
  }).formatToParts(/* @__PURE__ */ new Date());
  const hour = parts.find((part) => part.type === "hour")?.value ?? "00";
  const minute = parts.find((part) => part.type === "minute")?.value ?? "00";
  return `${hour}:${minute}`;
}
function commandV2Response(options) {
  const container = new ContainerBuilder();
  const title = options.title ? shortTitle(options.title) : "";
  const lines = options.lines.slice(0, 6).map((line) => String(line).replace(/\r/g, "").trim()).filter(Boolean);
  if (title) {
    container.addTextDisplayComponents(new TextDisplayBuilder().setContent(`**${title}**`));
    if (lines.length) container.addSeparatorComponents(new SeparatorBuilder());
  }
  if (lines.length) {
    container.addTextDisplayComponents(new TextDisplayBuilder().setContent(lines.join("\n")));
  }
  if (options.imageUrl) {
    container.addSeparatorComponents(new SeparatorBuilder());
    container.addMediaGalleryComponents(
      new MediaGalleryBuilder().addItems(
        new MediaGalleryItemBuilder().setURL(options.imageUrl)
      )
    );
  }
  const username = options.requester.username.replace(/[\r\n]/g, "").slice(0, 80);
  const time = requesterTime();
  const avatar = options.requester.displayAvatarURL({ extension: "png", size: 64 });
  container.addSeparatorComponents(new SeparatorBuilder());
  container.addSectionComponents(
    new SectionBuilder().addTextDisplayComponents(
      new TextDisplayBuilder().setContent(`${username} taraf\u0131ndan istendi \u2022 ${time}`)
    ).setThumbnailAccessory(new ThumbnailBuilder().setURL(avatar))
  );
  const bodyComponents = options.bodyComponents ?? [];
  const components = [...bodyComponents, container, ...options.actionRows ?? []];
  const basePayload = {
    flags: MessageFlags.IsComponentsV2,
    components
  };
  return options.ephemeral ? { ...basePayload, ephemeral: true } : basePayload;
}

// src/utils/afkService.ts
function formatAfkDuration(milliseconds) {
  const totalSeconds = Math.max(1, Math.floor(milliseconds / 1e3));
  if (totalSeconds < 60) return `${totalSeconds} saniye`;
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  if (minutes < 60) return seconds > 0 ? `${minutes} dakika ${seconds} saniye` : `${minutes} dakika`;
  const hours = Math.floor(minutes / 60);
  const remainingMinutes = minutes % 60;
  return remainingMinutes > 0 ? `${hours} saat ${remainingMinutes} dakika` : `${hours} saat`;
}
async function setAfkStatus(userId, reason, guildId, member) {
  dbService.setAfk(userId, reason, guildId);
  if (member?.manageable && !member.displayName.startsWith("[AFK]")) {
    const nickname = `[AFK] ${member.displayName}`.slice(0, 32);
    await member.setNickname(nickname).catch(() => null);
  }
}
async function clearAfkStatus(userId, member) {
  dbService.removeAfk(userId);
  if (member?.manageable && member.displayName.startsWith("[AFK]")) {
    const restoredName = member.displayName.replace(/^\[AFK\]\s*/, "");
    await member.setNickname(restoredName || null).catch(() => null);
  }
}

