function createProgressBar(current, max, length = 10) {
  if (max <= 0) return `[ \u25B1\u25B1\u25B1\u25B1\u25B1\u25B1\u25B1\u25B1\u25B1\u25B1 ] %0`;
  const percent = Math.min(100, Math.max(0, Math.round(current / max * 100)));
  const filled = Math.min(length, Math.max(0, Math.round(percent / 100 * length)));
  const empty = length - filled;
  const bar = "\u25B0".repeat(filled) + "\u25B1".repeat(empty);
  return `\`[ ${bar} ]\` **%${percent}**`;
}
function createEmbed(title, description, color) {
  const embed = new EmbedBuilder().setColor(color || EMBED_COLORS.primary).setTimestamp();
  if (title) {
    embed.setTitle(`\u27E6 ${title.replace(/[⟦⟧]/g, "").trim()} \u27E7`);
  }
  if (description) {
    embed.setDescription(description);
  }
  embed.setFooter({
    text: "Vega System \u2726 Premium Discord Suite"
  });
  return embed;
}
