var command = {
  data: new SlashCommandBuilder6().setName("ge\xE7ici-oda").setDescription("\u{1F399}\uFE0F Kendinize ait ge\xE7ici ses odan\u0131z\u0131 y\xF6netin.").addSubcommand(
    (sub) => sub.setName("ad").setDescription("Odan\u0131z\u0131n ismini de\u011Fi\u015Ftirin.").addStringOption(
      (opt) => opt.setName("isim").setDescription("Yeni oda ismi").setRequired(true).setMaxLength(50)
    )
  ).addSubcommand(
    (sub) => sub.setName("kilitle").setDescription("Odan\u0131z\u0131 kilitleyerek yabanc\u0131lar\u0131n girmesini engelleyin.")
  ).addSubcommand(
    (sub) => sub.setName("kilit-ac").setDescription("Odan\u0131z\u0131n kilidini a\xE7arak herkesin girmesine izin verin.")
  ).addSubcommand(
    (sub) => sub.setName("limit").setDescription("Odan\u0131za girebilecek maksimum ki\u015Fi say\u0131s\u0131n\u0131 belirleyin.").addIntegerOption(
      (opt) => opt.setName("sayi").setDescription("Ki\u015Fi say\u0131s\u0131 (0 = Limitsiz, 1-99)").setRequired(true).setMinValue(0).setMaxValue(99)
    )
  ).addSubcommand(
    (sub) => sub.setName("at").setDescription("Odan\u0131zdan bir kullan\u0131c\u0131y\u0131 at\u0131n.").addUserOption(
      (opt) => opt.setName("kullanici").setDescription("Odadan at\u0131lacak kullan\u0131c\u0131").setRequired(true)
    )
  ).addSubcommand(
    (sub) => sub.setName("gizle").setDescription("Odan\u0131z\u0131 sunucudaki di\u011Fer \xFCyelerden gizleyin.")
  ).addSubcommand(
    (sub) => sub.setName("goster").setDescription("Odan\u0131z\u0131 tekrar herkese g\xF6r\xFCn\xFCr yap\u0131n.")
  ),
  category: "genel",
  cooldown: 5,
  async execute(interaction) {
    try {
      if (!interaction.guildId || !interaction.guild) {
        return replyWithFooter(interaction, "\u274C Bu komut sadece sunucularda kullan\u0131labilir.");
      }
      const member = interaction.member;
      const voiceChannel = member.voice?.channel;
      if (!voiceChannel) {
        return replyWithFooter(interaction, "\u274C Bir ses kanal\u0131nda de\u011Filsiniz!");
      }
      const tempRoom = dbService.getTempVoiceChannel(voiceChannel.id);
      if (!tempRoom || tempRoom.owner_id !== interaction.user.id) {
        return replyWithFooter(interaction, "\u274C Bu ses odas\u0131n\u0131n sahibi siz de\u011Filsiniz veya bu bir ge\xE7ici ses odas\u0131 de\u011Fil!");
      }
      const subcommand = interaction.options.getSubcommand();
      if (subcommand === "ad") {
        const newName = interaction.options.getString("isim", true).trim();
        await voiceChannel.setName(newName).catch(() => {
        });
        return replyWithFooter(interaction, `\u2705 Ses odan\u0131z\u0131n ad\u0131 ba\u015Far\u0131yla **"${newName}"** olarak de\u011Fi\u015Ftirildi.`);
      }
      if (subcommand === "kilitle") {
        await voiceChannel.permissionOverwrites.edit(interaction.guild.roles.everyone, {
          Connect: false
        });
        dbService.updateTempVoiceChannel(voiceChannel.id, { isLocked: 1 });
        return replyWithFooter(interaction, "\u{1F512} Ses odan\u0131z kilitlendi! Art\u0131k davet etmedi\u011Finiz ki\u015Filer kat\u0131lamaz.");
      }
      if (subcommand === "kilit-ac") {
        await voiceChannel.permissionOverwrites.edit(interaction.guild.roles.everyone, {
          Connect: null
        });
        dbService.updateTempVoiceChannel(voiceChannel.id, { isLocked: 0 });
        return replyWithFooter(interaction, "\u{1F513} Ses odan\u0131z\u0131n kilidi a\xE7\u0131ld\u0131! Herkes kat\u0131labilir.");
      }
      if (subcommand === "limit") {
        const limit = interaction.options.getInteger("sayi", true);
        await voiceChannel.setUserLimit(limit);
        dbService.updateTempVoiceChannel(voiceChannel.id, { userLimit: limit });
        return replyWithFooter(interaction, `\u{1F465} Ses odan\u0131z\u0131n ki\u015Fi limiti **${limit === 0 ? "Limitsiz" : limit}** olarak ayarland\u0131.`);
      }
      if (subcommand === "at") {
        const targetUser = interaction.options.getUser("kullanici", true);
        if (targetUser.id === interaction.user.id) {
          return replyWithFooter(interaction, "\u274C Kendinizi odadan atamazs\u0131n\u0131z.");
        }
        const targetMember = interaction.guild.members.cache.get(targetUser.id);
        if (targetMember && targetMember.voice.channelId === voiceChannel.id) {
          await targetMember.voice.disconnect("Oda sahibi taraf\u0131ndan at\u0131ld\u0131");
          await voiceChannel.permissionOverwrites.edit(targetUser.id, { Connect: false });
          return replyWithFooter(interaction, `\u{1F462} **${targetUser.username}** odadan at\u0131ld\u0131 ve tekrar girmesi engellendi.`);
        } else {
          return replyWithFooter(interaction, "\u274C Belirtilen kullan\u0131c\u0131 sizin ses odan\u0131zda bulunmuyor.");
        }
      }
      if (subcommand === "gizle") {
        await voiceChannel.permissionOverwrites.edit(interaction.guild.roles.everyone, {
          ViewChannel: false
        });
        return replyWithFooter(interaction, "\u{1F441}\uFE0F\u200D\u{1F5E8}\uFE0F Ses odan\u0131z di\u011Fer \xFCyeler i\xE7in gizlendi.");
      }
      if (subcommand === "goster") {
        await voiceChannel.permissionOverwrites.edit(interaction.guild.roles.everyone, {
          ViewChannel: true
        });
        return replyWithFooter(interaction, "\u{1F441}\uFE0F Ses odan\u0131z tekrar herkese g\xF6r\xFCn\xFCr yap\u0131ld\u0131.");
      }
    } catch (error) {
      console.error("ge\xE7ici-oda command error:", error);
      const response = createResponse(interaction, "\u274C \u0130\u015Flem s\u0131ras\u0131nda bir hata olu\u015Ftu. L\xFCtfen tekrar deneyin.");
      if (interaction.replied || interaction.deferred) {
        return interaction.followUp(response);
      }
      return interaction.reply(response);
    }
  }
};

