  barGrad.addColorStop(0, "#9B59B6");
  barGrad.addColorStop(1, "#FF69B4");
  ctx.fillStyle = barGrad;
  roundRect(ctx, barX, barY, fillW, barH, 7);
  ctx.fill();
  ctx.font = "bold 22px sans-serif";
