    slap: "anime slap",
    sev: "anime pat head",
    kiss: "anime kiss",
    anime: "anime aesthetic",
    komik: "funny meme",
    hayvan: "cute animals cat dog",
    dans: "dance funny cool",
    ask: "love cute"
