// src/commands/bilgi/deprem.ts
import { SlashCommandBuilder as SlashCommandBuilder21, EmbedBuilder as EmbedBuilder6 } from "discord.js";
var VEGA_PURPLE5 = "#9B59B6";
var MAGNITUDE_COLORS = {
  high: "#EF4444",
  medium: "#F59E0B",
  low: "#22C55E"
};
var NUMBER_EMOJIS = ["1\uFE0F\u20E3", "2\uFE0F\u20E3", "3\uFE0F\u20E3", "4\uFE0F\u20E3", "5\uFE0F\u20E3", "6\uFE0F\u20E3", "7\uFE0F\u20E3", "8\uFE0F\u20E3", "9\uFE0F\u20E3", "\u{1F51F}"];
function getMagnitude(earthquake) {
  const rawMagnitude = earthquake.mag ?? earthquake.ml ?? 0;
  const magnitude = Number(String(rawMagnitude).replace(",", "."));
  return Number.isFinite(magnitude) ? magnitude : 0;
}
function getMagnitudeColor(earthquakes) {
  const highestMagnitude = Math.max(...earthquakes.map(getMagnitude));
  if (highestMagnitude >= 4) return MAGNITUDE_COLORS.high;
  if (highestMagnitude >= 3) return MAGNITUDE_COLORS.medium;
  return MAGNITUDE_COLORS.low;
}
function requesterFooter(interaction) {
  const requestedAt = new Intl.DateTimeFormat("tr-TR", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
    timeZone: "Europe/Istanbul"
  }).format(/* @__PURE__ */ new Date());
  return {
    text: `@${interaction.user.username} taraf\u0131ndan istendi \u2022 ${requestedAt}`,
    iconURL: interaction.user.displayAvatarURL()
  };
}
function unavailableEmbed(interaction) {
  return new EmbedBuilder6().setColor(VEGA_PURPLE5).setTitle("\u{1F30D} SON DEPREMLER").setDescription("\u274C Canl\u0131 deprem verisi \u015Fu anda al\u0131nam\u0131yor.\nL\xFCtfen birka\xE7 dakika sonra tekrar deneyin.").setFooter(requesterFooter(interaction));
}
var depremCommand = {
  data: new SlashCommandBuilder21().setName("deprem").setDescription("T\xFCrkiye ve \xE7evresinde ger\xE7ekle\u015Fen son depremleri listeler").addIntegerOption(
    (option) => option.setName("adet").setDescription("Listelenecek deprem say\u0131s\u0131 (1-10 aras\u0131, varsay\u0131lan 5)").setMinValue(1).setMaxValue(10).setRequired(false)
  ),
  category: "bilgi",
  cooldown: 10,
  async execute(interaction) {
    try {
      await interaction.deferReply();
      const count = Math.min(10, Math.max(1, interaction.options.getInteger("adet") ?? 5));
      let earthquakes = [];
      try {
        const response = await fetch("https://api.orhanaydogdu.com.tr/deprem/kandilli/live?limit=10", {
          headers: { "User-Agent": "VegaDiscordBot/1.0" }
        });
        if (response.ok) {
          const data = await response.json();
          if (data && Array.isArray(data.result)) {
            earthquakes = data.result.slice(0, count);
          }
        }
      } catch {
      }
      if (earthquakes.length === 0) {
        return interaction.editReply({ embeds: [unavailableEmbed(interaction)] });
      }
      const embed = new EmbedBuilder6().setColor(getMagnitudeColor(earthquakes)).setTitle("\u{1F30D} SON DEPREMLER").setDescription(
        `\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501
` + earthquakes.map((earthquake, index) => {
          const magnitude = getMagnitude(earthquake);
          const location = earthquake.title || earthquake.location || "Bilinmeyen Konum";
          const depth = earthquake.depth ?? "Bilinmiyor";
          const date = earthquake.date || "Az \xF6nce";
          return `${NUMBER_EMOJIS[index]} M ${magnitude} \u2022 ${location}
   \u23F1\uFE0F ${date} \u2022 ${depth === "Bilinmiyor" ? depth : `${depth} km`}`;
        }).join("\n")
      ).setFooter(requesterFooter(interaction));
      return interaction.editReply({ embeds: [embed] });
    } catch {
      return interaction.editReply({ embeds: [unavailableEmbed(interaction)] });
    }
  }
};
var deprem_default = depremCommand;

