import { SlashCommandBuilder as SlashCommandBuilder28 } from "discord.js";
var wikipediaCommand = {
  data: new SlashCommandBuilder28().setName("wikipedia").setDescription("T\xFCrk\xE7e Wikipedia \xFCzerinden k\u0131sa konu \xF6zeti getirir").addStringOption(
    (opt) => opt.setName("konu").setDescription("Bilgi almak istedi\u011Finiz konu").setRequired(true).setMaxLength(150)
  ),
  category: "Bilgi",
  cooldown: 5,
  async execute(interaction) {
    const query = interaction.options.getString("konu", true).trim().slice(0, 150);
    await interaction.deferReply();
    try {
      const url = `https://tr.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(query)}`;
      const response = await fetch(url, {
        headers: { "User-Agent": "VegaDiscordBot/8.0" },
        signal: AbortSignal.timeout(6e3)
      });
      if (response.status === 404) {
        return interaction.editReply(commandV2Response({
          requester: interaction.user,
          title: "Wikipedia",
          lines: [`\u201C${query}\u201D i\xE7in T\xFCrk\xE7e makale bulunamad\u0131.`, "Ba\u015Fka bir arama terimi deneyin."]
        }));
      }
      if (!response.ok) throw new Error(`Wikipedia HTTP ${response.status}`);
      const data = await response.json();
      const title = String(data.title || query).replace(/\s+/g, " ").slice(0, 65);
      const summary = String(data.extract || data.description || "Bu konu i\xE7in \xF6zet bulunamad\u0131.").replace(/\s+/g, " ").slice(0, 260);
      const pageUrl = String(data.content_urls?.desktop?.page || `https://tr.wikipedia.org/wiki/${encodeURIComponent(query)}`);
      let imageUrl;
      const rawImageUrl = data.originalimage?.source || data.thumbnail?.source;
      if (typeof rawImageUrl === "string") {
        try {
          const parsed = new URL(rawImageUrl);
          if (parsed.protocol === "https:" && /(^|\.)wikimedia\.org$/.test(parsed.hostname)) {
            imageUrl = parsed.toString();
          }
        } catch {
        }
      }
      return interaction.editReply(commandV2Response({
        requester: interaction.user,
        title: `Wikipedia \u2022 ${title}`,
        lines: [String(data.description || "T\xFCrk\xE7e Wikipedia \xF6zeti").slice(0, 120), summary, `Kaynak: <${pageUrl}>`],
        imageUrl
      }));
    } catch (error) {
      logger.warn(`Wikipedia API hatas\u0131: ${error?.message || "bilinmeyen hata"}`, "WikipediaCommand");
      return interaction.editReply(commandV2Response({
        requester: interaction.user,
        title: "Wikipedia",
        lines: ["Bilgi al\u0131namad\u0131. Daha sonra tekrar deneyin."]
      }));
    }
  }
};
