// src/commands/topluluk/rapor.ts
import {
  MessageFlags as MessageFlags26,
  ContainerBuilder as ContainerBuilder21,
  SeparatorBuilder as SeparatorBuilder20,
  SlashCommandBuilder as SlashCommandBuilder38,
  TextDisplayBuilder as TextDisplayBuilder21
} from "discord.js";
var raporCommand = {
  data: new SlashCommandBuilder38().setName("rapor").setDescription("\u{1F6A8} Kural ihlali yapan bir kullan\u0131c\u0131y\u0131 gizli olarak yetkililere bildirir.").addUserOption((opt) => opt.setName("kullan\u0131c\u0131").setDescription("Raporlamak istedi\u011Finiz kullan\u0131c\u0131").setRequired(true)).addStringOption(
    (opt) => opt.setName("kategori").setDescription("\u0130hlal kategorisi").setRequired(true).addChoices(
      { name: "\u{1F4E2} Reklam / Tan\u0131t\u0131m", value: "Reklam" },
      { name: "\u{1F92C} Hakaret / K\xFCf\xFCr / Toksisite", value: "Hakaret/K\xFCf\xFCr" },
      { name: "\u{1F4E8} Spam / Flood / Rahats\u0131z Etme", value: "Spam/Flood" },
      { name: "\u{1F51E} NSFW / Uygunsuz \u0130\xE7erik", value: "NSFW" },
      { name: "\u26A0\uFE0F Doland\u0131r\u0131c\u0131l\u0131k / \u015E\xFCpheli Ba\u011Flant\u0131", value: "Doland\u0131r\u0131c\u0131l\u0131k" },
      { name: "\u2753 Di\u011Fer \u0130hlal", value: "Di\u011Fer" }
    )
  ).addStringOption(
    (opt) => opt.setName("a\xE7\u0131klama").setDescription("Olay\u0131n detaylar\u0131, kan\u0131t bilgisi veya mesaj i\xE7eri\u011Fi").setRequired(true).setMaxLength(1e3)
  ),
  category: "Topluluk",
  cooldown: 10,
  async execute(interaction) {
    const guild = interaction.guild;
    if (!guild) {
      return interaction.reply({ content: "Bu komut sadece sunucularda kullan\u0131labilir.", flags: MessageFlags26.Ephemeral });
    }
    const targetUser = interaction.options.getUser("kullan\u0131c\u0131", true);
    const category = interaction.options.getString("kategori", true);
    const description = interaction.options.getString("a\xE7\u0131klama", true);
    if (targetUser.id === interaction.user.id) {
      return interaction.reply({ content: "\u274C Kendinizi raporlayamazs\u0131n\u0131z.", flags: MessageFlags26.Ephemeral });
    }
    if (targetUser.bot) {
      return interaction.reply({ content: "\u274C Botlar\u0131 kullan\u0131c\u0131 raporuyla \u015Fikayet edemezsiniz.", flags: MessageFlags26.Ephemeral });
    }
    const reportRes = dbService.createReport(guild.id, interaction.user.id, targetUser.id, category, description);
    const reportId = reportRes.id || Math.floor(1e3 + Math.random() * 9e3);
    const guildConfig = dbService.getGuild(guild.id);
    const logChannelId = guildConfig?.mod_log_channel || guildConfig?.log_channel;
    if (logChannelId) {
      const logChannel = guild.channels.cache.get(logChannelId);
      if (logChannel && logChannel.isTextBased()) {
        const modContainer = new ContainerBuilder21().setAccentColor(V2_COLORS.danger).addTextDisplayComponents(
          new TextDisplayBuilder21().setContent(`## \u{1F6A8} \u27E6 YEN\u0130 KULLANICI RAPORU #${reportId} \u27E7`)
        ).addSeparatorComponents(new SeparatorBuilder20()).addTextDisplayComponents(
          new TextDisplayBuilder21().setContent(
            `### \u{1F464} Raporlanan Kullan\u0131c\u0131:
\u2022 <@${targetUser.id}> (\`${targetUser.tag}\` - \`${targetUser.id}\`)

### \u{1F575}\uFE0F Raporlayan \xDCye:
\u2022 <@${interaction.user.id}> (\`${interaction.user.tag}\`)

### \u{1F3F7}\uFE0F \u0130hlal T\xFCr\xFC: \`${category}\`

### \u{1F4DD} A\xE7\u0131klama & Kan\u0131t:
> ${description.replace(/\n/g, "\n> ")}`
          )
        ).addSeparatorComponents(new SeparatorBuilder20()).addTextDisplayComponents(
          new TextDisplayBuilder21().setContent(`*Kanal: <#${interaction.channelId}> \u2022 Tarih: <t:${Math.floor(Date.now() / 1e3)}:f>*`)
        );
        try {
          await logChannel.send({
            flags: MessageFlags26.IsComponentsV2,
            components: [modContainer]
          });
        } catch {
        }
      }
    }
    const userContainer = new ContainerBuilder21().setAccentColor(V2_COLORS.success).addTextDisplayComponents(
      new TextDisplayBuilder21().setContent(`## \u2705 \u27E6 RAPORUNUZ ALINDI \u27E7`)
    ).addSeparatorComponents(new SeparatorBuilder20()).addTextDisplayComponents(
      new TextDisplayBuilder21().setContent(
        `**<@${targetUser.id}>** hakk\u0131ndaki \u015Fikayetiniz yetkili ekibine iletilmi\u015Ftir.

\u2022 **Rapor Numaras\u0131:** \`#${reportId}\`
\u2022 **Kategori:** \`${category}\`
\u2022 **Durum:** \u23F3 **\u0130nceleniyor**

*Topluluk kurallar\u0131n\u0131 korumam\u0131za yard\u0131mc\u0131 oldu\u011Funuz i\xE7in te\u015Fekk\xFCr ederiz.*`
      )
    );
    return interaction.reply({
      components: [userContainer],
      flags: MessageFlags26.Ephemeral | MessageFlags26.IsComponentsV2
    });
  }
};
var rapor_default = raporCommand;

