// src/utils/loggerChannel.ts
import { ChannelType as ChannelType5 } from "discord.js";
async function sendGuildLog(guild, type, embed) {
  if (!guild) return;
  try {
    const configData = dbService.getGuild(guild.id);
    let targetChannelId = null;
    switch (type) {
      case "mod":
        targetChannelId = configData.mod_log_channel || configData.log_channel;
        break;
      case "mesaj":
        targetChannelId = configData.mesaj_log_channel || configData.log_channel;
        break;
      case "ses":
        targetChannelId = configData.ses_log_channel || configData.log_channel;
        break;
      case "uye":
        targetChannelId = configData.uye_log_channel || configData.log_channel;
        break;
      case "rol":
        targetChannelId = configData.rol_log_channel || configData.log_channel;
        break;
      case "kanal":
        targetChannelId = configData.kanal_log_channel || configData.log_channel;
        break;
    }
    let channel = null;
    if (targetChannelId) {
      const cached = guild.channels.cache.get(targetChannelId);
      if (cached && cached.isTextBased()) {
        channel = cached;
      } else {
        const fetched = await guild.channels.fetch(targetChannelId).catch(() => null);
        if (fetched && fetched.isTextBased()) {
          channel = fetched;
        }
      }
    }
    if (!channel) {
      const namePatterns = {
        mesaj: ["mesaj-log", "mesaj_log", "message-log"],
        mod: ["mod-log", "mod_log", "moderasyon-log", "ceza-log"],
        ses: ["ses-log", "ses_log", "voice-log"],
        uye: ["\xFCye-log", "uye-log", "uye_log", "member-log"],
        rol: ["rol-log", "rol_log", "role-log"],
        kanal: ["kanal-log", "kanal_log", "channel-log"]
      };
      const patterns = namePatterns[type] || [];
      const found = guild.channels.cache.find(
        (c) => c.type === ChannelType5.GuildText && patterns.some((p) => c.name.toLowerCase().includes(p))
      );
      if (found && found.isTextBased()) {
        channel = found;
      }
    }
    if (channel) {
      await channel.send({ embeds: [embed] }).catch(() => null);
    }
  } catch {
  }
}

