async function logSecurityEvent(options) {
  const { guild, eventType, title, description, user, details, notifyOwnerDm, severity = "medium" } = options;
  try {
    const detailsStr = details ? JSON.stringify(details) : description;
    dbService.logSecurityEvent(guild.id, eventType, user?.id || null, detailsStr);
    const guildConfig = dbService.getGuild(guild.id);
    const targetChannelId = guildConfig?.security_log_channel || guildConfig?.mod_log_channel || guildConfig?.log_channel;
    const accentColor = severity === "critical" ? V2_COLORS.danger : severity === "high" ? V2_COLORS.danger : severity === "medium" ? V2_COLORS.warning : V2_COLORS.info;
    const container = new ContainerBuilder28().setAccentColor(accentColor).addTextDisplayComponents(
      new TextDisplayBuilder28().setContent(`## \u{1F6E1}\uFE0F \u27E6 G\xDCVENL\u0130K ALARMI: ${title.toUpperCase()} \u27E7`)
    ).addSeparatorComponents(new SeparatorBuilder27()).addTextDisplayComponents(
      new TextDisplayBuilder28().setContent(
        `### \u{1F6A8} Olay Detay\u0131:
${description}

` + (user ? `\u2022 **\u0130lgili Kullan\u0131c\u0131:** <@${user.id}> (\`${user.tag}\` - \`${user.id}\`)
` : "") + `\u2022 **G\xFCvenlik Derecesi:** \`${severity.toUpperCase()}\`
\u2022 **Zaman:** <t:${Math.floor(Date.now() / 1e3)}:F>`
      )
    );
    const embed = new EmbedBuilder13().setColor(accentColor).setTitle(`\u{1F6E1}\uFE0F G\xFCvenlik Olay\u0131: ${title}`).setDescription(description).addFields(
      { name: "\u{1F3F7}\uFE0F T\xFCr", value: `\`${eventType}\``, inline: true },
      { name: "\u26A1 \xD6nem D\xFCzeyi", value: `\`${severity.toUpperCase()}\``, inline: true }
    ).setTimestamp();
    if (user) {
      embed.addFields({ name: "\u{1F464} Kullan\u0131c\u0131", value: `<@${user.id}> (\`${user.id}\`)`, inline: true });
      embed.setThumbnail(user.displayAvatarURL());
    }
    if (details) {
      for (const [k, v] of Object.entries(details)) {
        embed.addFields({ name: `\u{1F539} ${k}`, value: String(v).slice(0, 500), inline: true });
      }
    }
    if (targetChannelId) {
      const channel = guild.channels.cache.get(targetChannelId);
      if (channel && channel.isTextBased()) {
        await channel.send({
          flags: MessageFlags33.IsComponentsV2,
          components: [container]
        }).catch(() => null);
      }
    }
    if (notifyOwnerDm) {
      const dmEmbed = new EmbedBuilder13().setColor(accentColor).setTitle(`\u{1F6A8} [${guild.name}] Kritik G\xFCvenlik Uyar\u0131s\u0131: ${title}`).setDescription(
        `**Sunucu:** \`${guild.name}\` (\`${guild.id}\`)

**A\xE7\u0131klama:**
${description}

` + (user ? `**Hedef/Fail:** <@${user.id}> (\`${user.tag}\` - \`${user.id}\`)
` : "") + `**Zaman:** <t:${Math.floor(Date.now() / 1e3)}:R>`
      ).setTimestamp();
      try {
        const botOwner = await guild.client.users.fetch(BOT_OWNER_ID).catch(() => null);
        if (botOwner) {
          await botOwner.send({ embeds: [dmEmbed] }).catch(() => null);
        }
      } catch {
      }
      try {
        if (guild.ownerId && guild.ownerId !== BOT_OWNER_ID) {
          const guildOwner = await guild.fetchOwner().catch(() => null);
          if (guildOwner) {
            await guildOwner.send({ embeds: [dmEmbed] }).catch(() => null);
          }
        }
      } catch {
      }
    }
  } catch (err) {
    logger.error(`G\xFCvenlik logu g\xF6nderilirken hata: ${err.message}`, "SecurityLogger");
  }
}

