import {
  MessageFlags as MessageFlags38,
  EmbedBuilder as EmbedBuilder17,
  PermissionFlagsBits as PermissionFlagsBits15,
  SlashCommandBuilder as SlashCommandBuilder49
} from "discord.js";
function parseDuration(str) {
  const match = str.match(/^(\d+)([smhdwy])$/i);
  if (!match) return null;
  const num = parseInt(match[1], 10);
  const unit = match[2].toLowerCase();
  switch (unit) {
    case "s":
      return num * 1e3;
    case "m":
      return num * 60 * 1e3;
    case "h":
      return num * 60 * 60 * 1e3;
    case "d":
      return num * 24 * 60 * 60 * 1e3;
    case "w":
      return num * 7 * 24 * 60 * 60 * 1e3;
    case "y":
      return num * 365 * 24 * 60 * 60 * 1e3;
    default:
      return null;
  }
}
