// src/commands/yetkili/dogrulama-kur.ts
import {
  MessageFlags as MessageFlags40,
  SlashCommandBuilder as SlashCommandBuilder51,
  EmbedBuilder as EmbedBuilder19,
  ActionRowBuilder as ActionRowBuilder16,
  ButtonBuilder as ButtonBuilder15,
  ButtonStyle as ButtonStyle15,
  PermissionFlagsBits as PermissionFlagsBits16,
  ChannelType as ChannelType6
} from "discord.js";
var command4 = {
  data: new SlashCommandBuilder51().setName("do\u011Frulama-kur").setDescription("\u{1F6E1}\uFE0F Sunucuya girenler i\xE7in Canvas tabanl\u0131 g\xF6rsel Captcha do\u011Frulama sistemi kurar.").setDefaultMemberPermissions(PermissionFlagsBits16.Administrator).addChannelOption(
    (opt) => opt.setName("kanal").setDescription("Do\u011Frulama butonunun g\xF6nderilece\u011Fi kanal").addChannelTypes(ChannelType6.GuildText).setRequired(true)
  ).addRoleOption(
    (opt) => opt.setName("k\u0131s\u0131tl\u0131-rol").setDescription("Do\u011Frulanmam\u0131\u015F yeni \xFCyelere verilecek k\u0131s\u0131tl\u0131 / misafir rol\xFC").setRequired(true)
  ).addRoleOption(
    (opt) => opt.setName("\xFCye-rol\xFC").setDescription("Captcha do\u011Frulamas\u0131n\u0131 ge\xE7en \xFCyelere verilecek onayl\u0131 \xFCye rol\xFC").setRequired(true)
  ).addStringOption(
    (opt) => opt.setName("zorluk").setDescription("Captcha zorluk derecesi").setRequired(false).addChoices(
      { name: "\u{1F7E2} Kolay (4 Karakter)", value: "kolay" },
      { name: "\u{1F7E1} Orta (5 Karakter - Tavsiye)", value: "orta" },
      { name: "\u{1F534} Zor (6 Karakter)", value: "zor" }
    )
  ),
  category: "yetkili",
  cooldown: 10,
  async execute(interaction) {
    if (!interaction.guildId || !interaction.guild) {
      return interaction.reply({ content: "\u274C Bu komut sadece sunucularda \xE7al\u0131\u015F\u0131r.", flags: MessageFlags40.Ephemeral });
    }
    try {
      const channel = interaction.options.getChannel("kanal", true);
      const unverifiedRole = interaction.options.getRole("k\u0131s\u0131tl\u0131-rol", true);
      const verifiedRole = interaction.options.getRole("\xFCye-rol\xFC", true);
      const difficulty = interaction.options.getString("zorluk") || "orta";
      const guild = interaction.guild;
      const botMember = guild.members.me;
      if (channel.type !== ChannelType6.GuildText) {
        return interaction.reply({ content: "\u274C Kanal ve roller ayn\u0131 sunucuya ait olmal\u0131d\u0131r.", flags: MessageFlags40.Ephemeral });
      }
      if (!botMember?.permissions.has(PermissionFlagsBits16.ManageRoles) || botMember.roles.highest.comparePositionTo(unverifiedRole) <= 0 || botMember.roles.highest.comparePositionTo(verifiedRole) <= 0) {
        return interaction.reply({ content: "\u274C Botta **Rolleri Y\xF6net** izni olmal\u0131 ve botun en y\xFCksek rol\xFC iki do\u011Frulama rol\xFCn\xFCn de \xFCzerinde bulunmal\u0131d\u0131r.", flags: MessageFlags40.Ephemeral });
      }
      const channelPermissions = channel.permissionsFor(botMember);
      if (!channelPermissions?.has([
        PermissionFlagsBits16.ViewChannel,
        PermissionFlagsBits16.SendMessages,
        PermissionFlagsBits16.EmbedLinks,
        PermissionFlagsBits16.AttachFiles
      ])) {
        return interaction.reply({ content: "\u274C Botun do\u011Frulama kanal\u0131nda mesaj, embed ve dosya g\xF6nderme izinleri olmal\u0131d\u0131r.", flags: MessageFlags40.Ephemeral });
      }
      await interaction.deferReply({ flags: MessageFlags40.Ephemeral });
      const verifyRow = new ActionRowBuilder16().addComponents(
        new ButtonBuilder15().setCustomId("start_captcha_verify").setLabel("\u{1F6E1}\uFE0F Do\u011Frulamay\u0131 Ba\u015Flat (Captcha)").setStyle(ButtonStyle15.Success).setEmoji("\u2705")
      );
      const verifyEmbed = new EmbedBuilder19().setColor("#5865F2").setTitle(`\u{1F6E1}\uFE0F ${guild.name} \u2014 G\xFCvenlik Do\u011Frulamas\u0131`).setDescription(
        `Sunucumuza ho\u015F geldiniz! Sunucu g\xFCvenli\u011Fini sa\u011Flamak ve bot hesaplar\u0131 engellemek i\xE7in l\xFCtfen g\xF6rsel do\u011Frulama ad\u0131m\u0131n\u0131 tamamlay\u0131n.

\u{1F4DD} **Nas\u0131l Do\u011Frulan\u0131r\u0131m?**
1. A\u015Fa\u011F\u0131daki **"Do\u011Frulamay\u0131 Ba\u015Flat"** butonuna t\u0131klay\u0131n.
2. Size \xF6zel a\xE7\u0131lan g\xF6rseldeki g\xFCvenlik kodunu forma yaz\u0131n.
3. Do\u011Fru yazd\u0131\u011F\u0131n\u0131zda sunucu kanallar\u0131na eri\u015Fiminiz an\u0131nda a\xE7\u0131lacakt\u0131r.

\u26A0\uFE0F *3 kez hatal\u0131 giri\u015F yaparsan\u0131z 5 dakika g\xFCvenlik bekleme s\xFCresine girersiniz.*`
      ).setFooter({ text: "Vega G\xFCvenlik & Captcha Sistemi", iconURL: guild.iconURL() || void 0 }).setTimestamp();
      const panelMessage = await channel.send({ embeds: [verifyEmbed], components: [verifyRow] });
      try {
        dbService.setCaptchaSettings(guild.id, channel.id, unverifiedRole.id, verifiedRole.id, difficulty);
      } catch (error) {
        await panelMessage.delete().catch(() => null);
        throw error;
      }
      const replyEmbed = new EmbedBuilder19().setColor("#2ECC71").setTitle("\u2705 Captcha Do\u011Frulama Sistemi Kuruldu!").setDescription(
        `Do\u011Frulama mesaj\u0131 <#${channel.id}> kanal\u0131na g\xF6nderildi ve sistem aktif edildi.

\u2022 \u{1F512} **K\u0131s\u0131tl\u0131 Rol:** ${unverifiedRole}
\u2022 \u{1F513} **\xDCye Rol\xFC:** ${verifiedRole}
\u2022 \u{1F3AF} **Zorluk Seviyesi:** \`${difficulty.toUpperCase()}\`

Sistemi s\u0131f\u0131rlamak veya kapatmak i\xE7in: .do\u011Frulama-s\u0131f\u0131rla`
      ).setTimestamp();
      return interaction.editReply({ embeds: [replyEmbed] });
    } catch (error) {
      const payload = { content: "\u274C Captcha sistemi kurulamad\u0131. Bot izinlerini ve kanal/rol hiyerar\u015Fisini kontrol edin." };
      return interaction.deferred || interaction.replied ? interaction.editReply(payload).catch(() => null) : interaction.reply({ ...payload, flags: MessageFlags40.Ephemeral }).catch(() => null);
    }
  }
};

// src/commands/yetkili/dogrulama-sifirla.ts
import {
  MessageFlags as MessageFlags41,
  SlashCommandBuilder as SlashCommandBuilder52,
  PermissionFlagsBits as PermissionFlagsBits17
} from "discord.js";
var command5 = {
  data: new SlashCommandBuilder52().setName("do\u011Frulama-s\u0131f\u0131rla").setDescription("\u{1F6E1}\uFE0F Captcha do\u011Frulama sistemini s\u0131f\u0131rlar ve devre d\u0131\u015F\u0131 b\u0131rak\u0131r.").setDefaultMemberPermissions(PermissionFlagsBits17.Administrator),
  category: "yetkili",
  cooldown: 5,
  async execute(interaction) {
    if (!interaction.guildId) {
      return interaction.reply({ content: "\u274C Bu komut sadece sunucularda \xE7al\u0131\u015F\u0131r.", flags: MessageFlags41.Ephemeral });
    }
    const current = dbService.getCaptchaSettings(interaction.guildId);
    if (!current) {
      return interaction.reply({ content: "\u2139\uFE0F Bu sunucuda aktif bir do\u011Frulama sistemi bulunmuyor.", flags: MessageFlags41.Ephemeral });
    }
    dbService.deleteCaptchaSettings(interaction.guildId);
    return interaction.reply({
      content: "\u2705 Do\u011Frulama (Captcha) sistemi bu sunucu i\xE7in ba\u015Far\u0131yla devre d\u0131\u015F\u0131 b\u0131rak\u0131ld\u0131 ve ayarlar s\u0131f\u0131rland\u0131.",
      flags: MessageFlags41.Ephemeral
    });
  }
};

// src/commands/yetkili/durum-rol.ts
import {
  MessageFlags as MessageFlags42,
  SlashCommandBuilder as SlashCommandBuilder53,
  EmbedBuilder as EmbedBuilder20,
  PermissionFlagsBits as PermissionFlagsBits18
} from "discord.js";
var command6 = {
  data: new SlashCommandBuilder53().setName("durum-rol").setDescription("\u{1F3AD} Kullan\u0131c\u0131lar\u0131n \xF6zel durumlar\u0131nda (Status) belirli kelime oldu\u011Funda otomatik rol verir.").setDefaultMemberPermissions(PermissionFlagsBits18.ManageRoles).addSubcommand(
    (sub) => sub.setName("ayarla").setDescription("\xD6zel durum kelimesi ve verilecek rol kural\u0131 tan\u0131mlar.").addStringOption(
      (opt) => opt.setName("kelime").setDescription("Kullan\u0131c\u0131n\u0131n durumunda aranacak kelime (\xD6rn: Vega, discord.gg/sunucu)").setRequired(true)
    ).addRoleOption(
      (opt) => opt.setName("rol").setDescription("Kullan\u0131c\u0131ya verilecek rol").setRequired(true)
    )
  ).addSubcommand(
    (sub) => sub.setName("sil").setDescription("Kay\u0131tl\u0131 bir durum rol\xFC kural\u0131n\u0131 siler.").addStringOption(
      (opt) => opt.setName("kelime").setDescription("Silinecek durum kelimesi").setRequired(true)
    )
  ).addSubcommand(
    (sub) => sub.setName("liste").setDescription("Sunucuda aktif t\xFCm durum rol kurallar\u0131n\u0131 listeler.")
  ),
  category: "yetkili",
  cooldown: 5,
  async execute(interaction) {
    if (!interaction.guildId || !interaction.guild) {
      return interaction.reply({ content: "\u274C Bu komut sadece sunucularda kullan\u0131labilir.", flags: MessageFlags42.Ephemeral });
    }
    const subcommand = interaction.options.getSubcommand();
    if (subcommand === "ayarla") {
      const keyword = interaction.options.getString("kelime", true).trim();
      const role = interaction.options.getRole("rol", true);
      if (role.managed || role.id === interaction.guild.id) {
        return interaction.reply({
          content: "\u274C Bot entegrasyon rollerini veya @everyone rol\xFCn\xFC durum rol\xFC olarak atayamazs\u0131n\u0131z.",
          flags: MessageFlags42.Ephemeral
        });
      }
      const botMember = interaction.guild.members.me;
      if (botMember && botMember.roles.highest.position <= role.position) {
        return interaction.reply({
          content: `\u26A0\uFE0F Botun en y\xFCksek rol\xFC **${role.name}** rol\xFCnden daha a\u015Fa\u011F\u0131da oldu\u011Fu i\xE7in bu rol\xFC \xFCyelere veremez. L\xFCtfen bot rol\xFCn\xFC yukar\u0131 ta\u015F\u0131y\u0131n.`,
          flags: MessageFlags42.Ephemeral
        });
      }
      dbService.addStatusRole(interaction.guildId, keyword, role.id);
      const embed = new EmbedBuilder20().setColor("#2ECC71").setTitle("\u2705 Durum Rol\xFC Kural\u0131 Eklendi").setDescription(
        `Art\u0131k \xF6zel durumunda (Custom Status) **"${keyword}"** kelimesi ge\xE7en \xFCyelere otomatik olarak ${role} rol\xFC verilecek.
Kullan\u0131c\u0131 durumundan kelimeyi kald\u0131r\u0131rsa rol otomatik olarak geri al\u0131n\u0131r.`
      ).addFields(
        { name: "\u{1F50D} Aranan Kelime / C\xFCmle", value: `\`${keyword}\``, inline: true },
        { name: "\u{1F3AD} Verilecek Rol", value: `${role}`, inline: true }
      ).setFooter({ text: "Vega Durum Rol\xFC Sistemi \u2022 presenceUpdate ile anl\u0131k takip edilir" }).setTimestamp();
      return interaction.reply({ embeds: [embed] });
    }
    if (subcommand === "sil") {
      const keyword = interaction.options.getString("kelime", true).trim();
      const removed = dbService.removeStatusRole(interaction.guildId, keyword);
      if (!removed) {
        return interaction.reply({
          content: `\u274C **"${keyword}"** i\xE7in kay\u0131tl\u0131 bir durum rol\xFC kural\u0131 bulunamad\u0131.`,
          flags: MessageFlags42.Ephemeral
        });
      }
      return interaction.reply({
        content: `\u2705 **"${keyword}"** kelimesine ba\u011Fl\u0131 durum rol\xFC kural\u0131 ba\u015Far\u0131yla silindi.`
      });
    }
    if (subcommand === "liste") {
      const rules = dbService.getStatusRoles(interaction.guildId);
      if (rules.length === 0) {
        return interaction.reply({
          content: "\u2139\uFE0F Bu sunucuda hen\xFCz tan\u0131mlanm\u0131\u015F bir durum rol\xFC kural\u0131 yok. Eklemek i\xE7in `.durum-rol ayarla <kelime> <rol>` kullanabilirsiniz.",
          flags: MessageFlags42.Ephemeral
        });
      }
      const desc = rules.map((r, i) => `${i + 1}. \u{1F50D} Kelime: \`${r.keyword}\` \u27A1\uFE0F Rol: <@&${r.role_id}>`).join("\n");
      const embed = new EmbedBuilder20().setColor("#9B59B6").setTitle("\u{1F3AD} Aktif Durum Rol\xFC Kurallar\u0131").setDescription(desc).setFooter({ text: `Toplam ${rules.length} kural tan\u0131ml\u0131` }).setTimestamp();
      return interaction.reply({ embeds: [embed] });
    }
  }
};

