// src/commands/yetkili/mute.ts
import {
  MessageFlags as MessageFlags52,
  SlashCommandBuilder as SlashCommandBuilder63,
  PermissionFlagsBits as PermissionFlagsBits28,
  EmbedBuilder as EmbedBuilder28
} from "discord.js";
var muteCommand = {
  data: new SlashCommandBuilder63().setName("mute").setDescription("\u{1F507} Bir \xFCyeyi belirtilen s\xFCre boyunca susturur (zamana\u015F\u0131m\u0131 / timeout)").addUserOption(
    (option) => option.setName("kullan\u0131c\u0131").setDescription("Susturulacak \xFCye").setRequired(true)
  ).addIntegerOption(
    (option) => option.setName("dakika").setDescription("Susturma s\xFCresi (dakika olarak)").setMinValue(1).setMaxValue(40320).setRequired(true)
  ).addStringOption(
    (option) => option.setName("sebep").setDescription("Susturma gerek\xE7esi").setRequired(false)
  ).setDefaultMemberPermissions(PermissionFlagsBits28.ModerateMembers),
  category: "yetkili",
  cooldown: 5,
  async execute(interaction) {
    try {
      const guild = interaction.guild;
      if (!guild) {
        return interaction.reply({ embeds: [errorEmbed("Bu komut yaln\u0131zca sunucularda kullan\u0131labilir.")], flags: MessageFlags52.Ephemeral });
      }
      if (!interaction.memberPermissions?.has(PermissionFlagsBits28.ModerateMembers)) {
        return interaction.reply({ embeds: [errorEmbed("Susturma i\xE7in **\xDCyeleri Zaman A\u015F\u0131m\u0131na U\u011Frat** yetkisi gerekir.")], flags: MessageFlags52.Ephemeral });
      }
      const userOption = interaction.options.getUser("kullan\u0131c\u0131", true);
      const userId = typeof userOption === "string" ? userOption : userOption.id;
      const member = await guild.members.fetch(userId).catch(() => null);
      if (!member) {
        return interaction.reply({ embeds: [errorEmbed("Kullan\u0131c\u0131 bu sunucuda bulunamad\u0131.", "KULLANICI BULUNAMADI")], flags: MessageFlags52.Ephemeral });
      }
      const user = typeof userOption === "string" ? member.user : userOption;
      const minutes = interaction.options.getInteger("dakika", true);
      const reason = interaction.options.getString("sebep") || "Sebep belirtilmedi";
      if (!Number.isInteger(minutes) || minutes < 1 || minutes > 40320) {
        return interaction.reply({ embeds: [errorEmbed("S\xFCre 1\u201340.320 dakika aral\u0131\u011F\u0131nda olmal\u0131d\u0131r.")], flags: MessageFlags52.Ephemeral });
      }
      if (user.id === interaction.user.id) {
        return interaction.reply({ embeds: [errorEmbed("Kendinizi susturamazs\u0131n\u0131z.", "GE\xC7ERS\u0130Z HEDEF")], flags: MessageFlags52.Ephemeral });
      }
      if (!member.moderatable) {
        return interaction.reply({ embeds: [errorEmbed("Bu \xFCyeyi susturmak i\xE7in yetkim yetersiz (rol hiyerar\u015Fisi nedeniyle).", "YETK\u0130 YETERS\u0130Z")], flags: MessageFlags52.Ephemeral });
      }
      if (!guild.members.me?.permissions.has(PermissionFlagsBits28.ModerateMembers)) {
        return interaction.reply({ embeds: [errorEmbed("Botta **\xDCyeleri Zaman A\u015F\u0131m\u0131na U\u011Frat** izni bulunmuyor.")], flags: MessageFlags52.Ephemeral });
      }
      const durationMs = minutes * 60 * 1e3;
      await member.timeout(durationMs, `${reason} (Yetkili: ${interaction.user.tag})`);
      const embed = new EmbedBuilder28().setColor("#F59E0B").setAuthor({
        name: "VEGA SECURITY CORE \u2022 SUSTURMA TUTANA\u011EI",
        iconURL: interaction.client.user?.displayAvatarURL()
      }).setTitle("\u{1F507} \u27E6 CEZA B\u0130LD\u0130R\u0130M\u0130: \xDCYE SUSTURULDU (TIMEOUT) \u27E7").setThumbnail(user.displayAvatarURL({ size: 256 })).setDescription(
        `\`\`\`yaml
\u250C\u2500\u2500 [ MODERASYON SUSTURMA TUTANA\u011EI ] \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
\u2502 Hedef \xDCye   : ${user.tag.padEnd(24)}
\u2502 S\xFCre (Dakika): ${minutes.toString().padEnd(24)}
\u2502 Yetkili     : ${interaction.user.tag.padEnd(24)}
\u2502 Ceza Sebebi : ${reason.slice(0, 24).padEnd(24)}
\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
\`\`\`
>>> \u25AB\uFE0F **Susturulan:** <@${user.id}> (\`${user.id}\`)
\u25AB\uFE0F **Yetkili:** <@${interaction.user.id}>
\u25AB\uFE0F **S\xFCre:** \`${minutes} Dakika\` \u2022 **Biti\u015F:** <t:${Math.floor((Date.now() + durationMs) / 1e3)}:R>`
      ).addFields(
        {
          name: "\u{1F464} Hedef \xDCye",
          value: `>>> <@${user.id}>
\`${user.tag}\``,
          inline: true
        },
        {
          name: "\u23F1\uFE0F Susturma S\xFCresi",
          value: `>>> \`${minutes} Dakika\`
<t:${Math.floor((Date.now() + durationMs) / 1e3)}:t>`,
          inline: true
        },
        {
          name: "\u{1F4CB} Ceza Sebebi",
          value: `>>> \`${reason}\``,
          inline: true
        }
      ).setFooter({ text: "Vega Moderation \u2726 Zaman A\u015F\u0131m\u0131 Protokol\xFC \u2022 v8.5" }).setTimestamp();
      return interaction.reply({ embeds: [embed] });
    } catch (error) {
      return interaction.reply({ embeds: [errorEmbed("Susturma i\u015Flemi s\u0131ras\u0131nda beklenmeyen bir hata olu\u015Ftu.")], flags: MessageFlags52.Ephemeral });
    }
  }
};
