    new StringSelectMenuOptionBuilder3().setLabel("Yar\u0131\u015F\u0131yor: ...").setValue("status_competing").setDescription("Botun yar\u0131\u015Ft\u0131\u011F\u0131 etkinli\u011Fi ayarlar").setEmoji("\u{1F3C6}")
