function buildWelcomePanel(guild) {
  const guildConfig = dbService.getGuild(guild.id);
  const cardStatus = guildConfig.welcome_card !== 0;
  let autoRolesText = "`Ayarlanmam\u0131\u015F`";
  if (guildConfig.auto_roles) {
    try {
      const parsed = JSON.parse(guildConfig.auto_roles);
      if (Array.isArray(parsed) && parsed.length > 0) {
        autoRolesText = parsed.map((id) => `<@&${id}>`).join(", ");
      }
    } catch {
    }
  }
  const embed = new EmbedBuilder31().setColor("#9B59B6").setTitle("\u{1F6AA} Ho\u015Fgeldin Sistemi Y\xF6netimi").setDescription(
    `Sunucuya yeni kat\u0131lan \xFCyeler i\xE7in kar\u015F\u0131lama mesaj\u0131, kanal\u0131 ve otorol ayarlar\u0131:

\u2022 **Ho\u015Fgeldin Kanal\u0131:** ${guildConfig.welcome_channel ? `<#${guildConfig.welcome_channel}>` : "`Ayarlanmam\u0131\u015F`"}
\u2022 **G\xF6rsel Ho\u015Fgeldin Kart\u0131:** ${cardStatus ? "\u{1F7E2} A\xE7\u0131k" : "\u{1F534} Kapal\u0131"}
\u2022 **Oto-Roller:** ${autoRolesText}
\u2022 **\xD6zel Mesaj:** 
>>> ${guildConfig.welcome_message || "*Varsay\u0131lan mesaj kullan\u0131l\u0131yor: Ho\u015F geldin {user}!*"}`
  ).setFooter({ text: "A\u015Fa\u011F\u0131daki men\xFClerden kanal\u0131 veya rol\xFC an\u0131nda se\xE7ebilirsiniz." });
  const channelRow = new ActionRowBuilder18().addComponents(
    new ChannelSelectMenuBuilder().setCustomId("panel_sel_welcome_channel").setPlaceholder("\u{1F4CD} Ho\u015Fgeldin kanal\u0131n\u0131 se\xE7in...").setChannelTypes([ChannelType16.GuildText])
  );
  const roleRow = new ActionRowBuilder18().addComponents(
    new RoleSelectMenuBuilder().setCustomId("panel_sel_autorole").setPlaceholder("\u{1F451} Otomatik verilecek rolleri se\xE7in...").setMinValues(1).setMaxValues(5)
  );
  const buttonRow = new ActionRowBuilder18().addComponents(
    new ButtonBuilder17().setCustomId("panel_btn_welcome_msg").setLabel("Mesaj Yaz").setEmoji("\u270F\uFE0F").setStyle(ButtonStyle17.Primary),
    new ButtonBuilder17().setCustomId("panel_toggle_welcome_card").setLabel(cardStatus ? "Kart\u0131 Kapat" : "Kart\u0131 A\xE7").setEmoji("\u{1F5BC}\uFE0F").setStyle(cardStatus ? ButtonStyle17.Danger : ButtonStyle17.Success),
    new ButtonBuilder17().setCustomId("panel_reset_welcome").setLabel("S\u0131f\u0131rla").setEmoji("\u{1F5D1}\uFE0F").setStyle(ButtonStyle17.Secondary),
    new ButtonBuilder17().setCustomId("panel_main").setLabel("Ana Panel").setEmoji("\u{1F3E0}").setStyle(ButtonStyle17.Primary),
    new ButtonBuilder17().setCustomId("panel_exit").setLabel("Kapat").setEmoji("\u274C").setStyle(ButtonStyle17.Danger)
  );
  return { embed, components: [channelRow, roleRow, buttonRow] };
}
