function buildDetailedStatsPanel(guild, client2) {
  const memberCount = guild.memberCount;
  const botCount = guild.members.cache.filter((m) => m.user.bot).size;
  const humanCount = memberCount - botCount;
  let lastCommandsText = "Son zamanlarda komut kullan\u0131m\u0131 kaydedilmedi.";
  try {
    const logs = dbService.getRecentCommandLogs(5, guild.id) || [];
    if (logs.length > 0) {
      lastCommandsText = logs.map((l) => `\u2022 \`/${l.command}\` \u2014 <@${l.user_id}> (<t:${Math.floor(new Date(l.used_at).getTime() / 1e3)}:R>)`).join("\n");
    }
  } catch {
  }
  const embed = new EmbedBuilder31().setColor("#9B59B6").setTitle(`\u{1F4C8} ${guild.name} \u2022 Detayl\u0131 Sunucu & Kullan\u0131m \u0130statistikleri`).setDescription(
    `Sunucunuzun b\xFCy\xFCme oranlar\u0131, \xFCye kompozisyonu ve bot aktivite verileri:

\u{1F465} **\xDCye Demografisi:**
\u2022 Toplam \xDCye: **${memberCount}**
\u2022 Ger\xE7ek Kullan\u0131c\u0131: **${humanCount}** (%%${Math.round(humanCount / memberCount * 100)})
\u2022 Botlar: **${botCount}** (%%${Math.round(botCount / memberCount * 100)})

\u{1F4C1} **Kanal & Rol Say\u0131lar\u0131:**
\u2022 Metin / Ses Kanallar\u0131: **${guild.channels.cache.size}**
\u2022 Rol Say\u0131s\u0131: **${guild.roles.cache.size}**
\u2022 \xD6zel Emojiler: **${guild.emojis.cache.size}**

\u26A1 **Son Kullan\u0131lan Komutlar:**
${lastCommandsText}`
  ).setFooter({ text: "Vega Analytics Engine \u2022 Canl\u0131 SQLite Verileri" }).setTimestamp();
  const buttonRow = new ActionRowBuilder18().addComponents(
    new ButtonBuilder17().setCustomId("panel_view_stats").setLabel("Yenile").setEmoji("\u{1F504}").setStyle(ButtonStyle17.Primary),
    new ButtonBuilder17().setCustomId("panel_main").setLabel("Ana Panel").setEmoji("\u{1F3E0}").setStyle(ButtonStyle17.Primary),
    new ButtonBuilder17().setCustomId("panel_exit").setLabel("Kapat").setEmoji("\u274C").setStyle(ButtonStyle17.Danger)
  );
  return { embed, components: [buttonRow] };
}
function buildGeneralPanel(guild, client2) {
  const totalGuilds = client2.guilds.cache.size;
  const totalUsers = client2.guilds.cache.reduce((acc, g) => acc + g.memberCount, 0);
  const ping = client2.ws.ping;
  const uptimeSeconds = Math.floor((client2.uptime || 0) / 1e3);
  const uptimeHours = Math.floor(uptimeSeconds / 3600);
  const uptimeMins = Math.floor(uptimeSeconds % 3600 / 60);
  const memUsage = process.memoryUsage();
  const ramMb = Math.round(memUsage.heapUsed / 1024 / 1024);
  const totalRamMb = Math.round(os.totalmem() / 1024 / 1024);
  const cpuLoad = (os.loadavg()[0] || 0.1).toFixed(2);
  const embed = new EmbedBuilder31().setColor("#9B59B6").setTitle(`\u{1F4CA} Vega Bot Donan\u0131m & Sistem Durumu`).setThumbnail(client2.user?.displayAvatarURL() || null).addFields(
    { name: "\u{1F310} Sunucu Say\u0131s\u0131", value: `\`${totalGuilds}\` sunucu`, inline: true },
    { name: "\u{1F465} Kullan\u0131c\u0131 Say\u0131s\u0131", value: `\`${totalUsers.toLocaleString("tr-TR")}\` kullan\u0131c\u0131`, inline: true },
    { name: "\u26A1 Bot Ping (WebSocket)", value: `\`${ping}ms\``, inline: true },
    { name: "\u23F1\uFE0F \xC7al\u0131\u015Fma S\xFCresi (Uptime)", value: `\`${uptimeHours}s ${uptimeMins}d\``, inline: true },
    { name: "\u{1F9E0} RAM Kullan\u0131m\u0131", value: `\`${ramMb} MB\` / \`${totalRamMb} MB\``, inline: true },
    { name: "\u{1F4BB} CPU Y\xFCk\xFC", value: `\`%${cpuLoad}\``, inline: true },
    { name: "\u{1F680} S\xFCr\xFCm & Mimari", value: "`v12.0.0 (Faz 12)`", inline: true },
    { name: "\u{1F916} Toplam Slash Komut", value: `\`${client2.commands.size} / 100\` (S\u0131n\u0131r Uyumlu)`, inline: true },
    { name: "\u{1F4BE} Veritaban\u0131", value: "`SQLite 3 (WAL Modu)`", inline: true }
  ).setFooter({ text: "Vega Control Center v12.0 \u2022 Y\xFCksek Performansl\u0131 Discord Botu" }).setTimestamp();
  const buttonRow = new ActionRowBuilder18().addComponents(
    new ButtonBuilder17().setCustomId("panel_view_general").setLabel("Yenile").setEmoji("\u{1F504}").setStyle(ButtonStyle17.Primary),
    new ButtonBuilder17().setCustomId("panel_main").setLabel("Ana Panel").setEmoji("\u{1F3E0}").setStyle(ButtonStyle17.Primary),
    new ButtonBuilder17().setCustomId("panel_exit").setLabel("Kapat").setEmoji("\u274C").setStyle(ButtonStyle17.Danger)
  );
  return { embed, components: [buttonRow] };
}

// src/commands/yetkili/panel.ts
var panelCommand = {
  data: new SlashCommandBuilder66().setName("panel").setDescription("\u{1F39B}\uFE0F Vega \u0130nteraktif Sunucu Y\xF6netim ve Ayar Kontrol Panelini a\xE7ar").setDefaultMemberPermissions(PermissionFlagsBits31.ManageGuild),
  category: "Yetkili",
  cooldown: 5,
  async execute(interaction) {
    try {
      const guild = interaction.guild;
      if (!guild) {
        return interaction.reply({
          content: "\u274C Bu komut yaln\u0131zca bir sunucu i\xE7erisinde kullan\u0131labilir.",
          flags: MessageFlags55.Ephemeral
        });
      }
      const member = interaction.member;
      const isOwner = guild.ownerId === interaction.user.id;
      const isBotOwner = interaction.user.id === config.ownerId;
      const isAdmin = member.permissions.has(PermissionFlagsBits31.Administrator) || member.permissions.has(PermissionFlagsBits31.ManageGuild);
      const staffRoleId = dbService.getStaffRole(guild.id);
      const hasStaffRole = Boolean(staffRoleId && member.roles?.cache?.has(staffRoleId));
      if (!isOwner && !isBotOwner && !isAdmin && !hasStaffRole) {
        return interaction.reply({
          content: "\u274C Bu kontrol panelini yaln\u0131zca **Sunucu Yetkilileri** veya **Y\xF6neticiler** a\xE7abilir.",
          flags: MessageFlags55.Ephemeral
        });
      }
      const client2 = interaction.client;
      const { embed, components } = buildMainPanel(guild, client2);
      await interaction.reply({
        embeds: [embed],
        components
      });
    } catch (error) {
      if (interaction.deferred || interaction.replied) {
        await interaction.editReply({ content: "\u274C Y\xF6netim paneli a\xE7\u0131l\u0131rken bir hata olu\u015Ftu." }).catch(() => null);
      } else {
        await interaction.reply({ content: "\u274C Y\xF6netim paneli a\xE7\u0131l\u0131rken bir hata olu\u015Ftu.", flags: MessageFlags55.Ephemeral }).catch(() => null);
      }
    }
  }
};
var panel_default = panelCommand;

