import {
  MessageFlags as MessageFlags57,
  SlashCommandBuilder as SlashCommandBuilder68,
  PermissionFlagsBits as PermissionFlagsBits33
} from "discord.js";
var rolAlCommand = {
  data: new SlashCommandBuilder68().setName("rol-al").setDescription("Belirtilen \xFCyeden bir rol\xFC geri al\u0131r").addUserOption(
    (option) => option.setName("kullan\u0131c\u0131").setDescription("Rol\xFC al\u0131nacak \xFCye").setRequired(true)
  ).addRoleOption(
    (option) => option.setName("rol").setDescription("Al\u0131nacak rol").setRequired(true)
  ).setDefaultMemberPermissions(PermissionFlagsBits33.ManageRoles),
  category: "yetkili",
  cooldown: 3,
  async execute(interaction) {
    try {
      const user = interaction.options.getUser("kullan\u0131c\u0131", true);
      const role = interaction.options.getRole("rol", true);
      const member = interaction.guild?.members.cache.get(user.id);
      if (!member) {
        return interaction.reply({ embeds: [errorEmbed("Kullan\u0131c\u0131 sunucuda bulunamad\u0131.")], flags: MessageFlags57.Ephemeral });
      }
      if (!member.roles.cache.has(role.id)) {
        return interaction.reply({ embeds: [errorEmbed("Bu kullan\u0131c\u0131 zaten bu role sahip de\u011Fil.")], flags: MessageFlags57.Ephemeral });
      }
      const botMember = interaction.guild?.members.me;
      if (botMember && role.position >= botMember.roles.highest.position) {
        return interaction.reply({ embeds: [errorEmbed("Bu rol benim yetkimden daha y\xFCksekte oldu\u011Fu i\xE7in alam\u0131yorum.")], flags: MessageFlags57.Ephemeral });
      }
      await member.roles.remove(role, `Yetkili: ${interaction.user.tag}`);
      return interaction.reply({
        embeds: [successEmbed(`**${user.tag}** kullan\u0131c\u0131s\u0131ndan ${role} rol\xFC ba\u015Far\u0131yla al\u0131nd\u0131.`)]
      });
    } catch (error) {
      return interaction.reply({ embeds: [errorEmbed()], flags: MessageFlags57.Ephemeral });
    }
  }
};
var rol_al_default = rolAlCommand;

