// src/commands/yetkili/sil.ts
import {
  MessageFlags as MessageFlags62,
  SlashCommandBuilder as SlashCommandBuilder73,
  PermissionFlagsBits as PermissionFlagsBits38,
  EmbedBuilder as EmbedBuilder36
} from "discord.js";
var silCommand = {
  data: new SlashCommandBuilder73().setName("sil").setDescription("Belirtilen miktarda mesaj\u0131 kanaldan topluca siler").addIntegerOption(
    (option) => option.setName("miktar").setDescription("Silinecek mesaj say\u0131s\u0131 (1-100 aras\u0131)").setMinValue(1).setMaxValue(100).setRequired(true)
  ).addUserOption(
    (option) => option.setName("kullan\u0131c\u0131").setDescription("Sadece bu kullan\u0131c\u0131n\u0131n mesajlar\u0131n\u0131 sil").setRequired(false)
  ).setDefaultMemberPermissions(PermissionFlagsBits38.ManageMessages),
  category: "yetkili",
  cooldown: 3,
  async execute(interaction) {
    try {
      if (!interaction.guild || !interaction.memberPermissions?.has(PermissionFlagsBits38.ManageMessages)) {
        return interaction.reply({ embeds: [errorEmbed("Bu komut i\xE7in **Mesajlar\u0131 Y\xF6net** yetkisi gerekir.")], flags: MessageFlags62.Ephemeral });
      }
      const amount = interaction.options.getInteger("miktar", true);
      const targetUser = interaction.options.getUser("kullan\u0131c\u0131");
      const channel = interaction.channel;
      if (!channel || !channel.isTextBased()) {
        return interaction.reply({ embeds: [errorEmbed("Bu komut yaln\u0131zca metin kanallar\u0131nda kullan\u0131labilir.")], flags: MessageFlags62.Ephemeral });
      }
      const botMember = interaction.guild.members.me;
      if (!botMember || !channel.permissionsFor(botMember)?.has([
        PermissionFlagsBits38.ViewChannel,
        PermissionFlagsBits38.ReadMessageHistory,
        PermissionFlagsBits38.ManageMessages
      ])) {
        return interaction.reply({ embeds: [errorEmbed("Botun bu kanalda **Kanal\u0131 G\xF6r\xFCnt\xFCle**, **Mesaj Ge\xE7mi\u015Fini Oku** ve **Mesajlar\u0131 Y\xF6net** izinleri olmal\u0131d\u0131r.", "BOT YETK\u0130S\u0130 YETERS\u0130Z")], flags: MessageFlags62.Ephemeral });
      }
      await interaction.deferReply({ flags: MessageFlags62.Ephemeral });
      const messages = await channel.messages.fetch({ limit: targetUser ? 100 : amount });
      const messagesToDelete = targetUser ? messages.filter((m) => m.author.id === targetUser.id).first(amount) : messages;
      const deleted = await channel.bulkDelete(messagesToDelete, true);
      const receiptEmbed = new EmbedBuilder36().setColor("#10B981").setAuthor({
        name: "VEGA MODERASYON \u2022 TEM\u0130ZL\u0130K PROTOKOL\xDC",
        iconURL: interaction.client.user?.displayAvatarURL()
      }).setTitle("\u{1F9F9} \u27E6 TOPLU MESAJ TEM\u0130ZLEND\u0130 \u27E7").setDescription(
        `\u250F\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2513
\u2503 \u25AB\uFE0F Kanal:    #${channel.name}
\u2503 \u25AB\uFE0F Silinen:  ${deleted.size} Adet Mesaj
\u2503 \u25AB\uFE0F Filtre:   ${targetUser ? targetUser.username : "T\xFCm Mesajlar"}
\u2503 \u25AB\uFE0F Yetkili:  ${interaction.user.username}
\u2517\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u251B`
      ).addFields(
        {
          name: "\u{1F4CA} \u27E6 \u0130\u015ELEM AYRINTILARI \u27E7",
          value: `>>> \u25AA\uFE0F Hedef Say\u0131: \`${amount}\`
\u25AA\uFE0F Ba\u015Far\u0131yla Kald\u0131r\u0131lan: \`${deleted.size}\`
\u25AA\uFE0F Durum: \`Optimal Temizlik Tamamland\u0131\``,
          inline: false
        }
      ).setFooter({ text: "Vega Moderation \u2726 Sohbet Temizleme Sistemi" }).setTimestamp();
      await interaction.editReply({
        embeds: [receiptEmbed]
      });
      const cleanupTimer = setTimeout(() => {
        void interaction.deleteReply().catch(() => null);
      }, 5e3);
      cleanupTimer.unref?.();
      return;
    } catch (error) {
      const message = error instanceof Error && /permission|missing access|50013/i.test(error.message) ? "Botun bu kanalda mesajlar\u0131 g\xF6r\xFCnt\xFCleme, ge\xE7mi\u015Fi okuma veya silme izni yok." : "Mesajlar silinemedi. 14 g\xFCnden eski mesajlar toplu silinemez; kanal ve bot izinlerini kontrol edin.";
      return interaction.editReply({ embeds: [errorEmbed(message)] }).catch(() => null);
    }
  }
};
var sil_default = silCommand;

