// src/commands/seviye/xp.ts
import {
  MessageFlags as MessageFlags78,
  SlashCommandBuilder as SlashCommandBuilder91,
  PermissionFlagsBits as PermissionFlagsBits51
} from "discord.js";
var xpCommand = {
  data: new SlashCommandBuilder91().setName("xp").setDescription("Bir kullan\u0131c\u0131n\u0131n XP miktar\u0131n\u0131 d\xFCzenler (Ekle, Sil, S\u0131f\u0131rla)").addSubcommand(
    (sub) => sub.setName("ekle").setDescription("Kullan\u0131c\u0131ya XP ekler").addUserOption(
      (opt) => opt.setName("kullan\u0131c\u0131").setDescription("XP eklenecek kullan\u0131c\u0131").setRequired(true)
    ).addIntegerOption(
      (opt) => opt.setName("miktar").setDescription("Eklenecek XP miktar\u0131").setMinValue(1).setRequired(true)
    )
  ).addSubcommand(
    (sub) => sub.setName("sil").setDescription("Kullan\u0131c\u0131dan belirtilen miktarda XP siler").addUserOption(
      (opt) => opt.setName("kullan\u0131c\u0131").setDescription("XP silinecek kullan\u0131c\u0131").setRequired(true)
    ).addIntegerOption(
      (opt) => opt.setName("miktar").setDescription("Silinecek XP miktar\u0131").setMinValue(1).setRequired(true)
    )
  ).addSubcommand(
    (sub) => sub.setName("s\u0131f\u0131rla").setDescription("Kullan\u0131c\u0131n\u0131n t\xFCm XP ve seviyesini s\u0131f\u0131rlar").addUserOption(
      (opt) => opt.setName("kullan\u0131c\u0131").setDescription("XPsi s\u0131f\u0131rlanacak kullan\u0131c\u0131").setRequired(true)
    )
  ).setDefaultMemberPermissions(PermissionFlagsBits51.ManageGuild),
  category: "Seviye",
  cooldown: 5,
  async execute(interaction) {
    try {
      const subcommand = interaction.options.getSubcommand();
      const user = interaction.options.getUser("kullan\u0131c\u0131", true);
      const guildId = interaction.guildId;
      if (subcommand === "ekle") {
        const amount = interaction.options.getInteger("miktar", true);
        const result = dbService.addXp(user.id, guildId, amount);
        return interaction.reply({
          embeds: [successEmbed(`**${user.tag}** kullan\u0131c\u0131s\u0131na **${amount.toLocaleString("tr-TR")} XP** eklendi.
Yeni Seviye: \`${result.newLevel}\` (Toplam: \`${result.user.xp.toLocaleString("tr-TR")} XP\`)`)]
        });
      } else if (subcommand === "sil") {
        const amount = interaction.options.getInteger("miktar", true);
        const currentData = dbService.getUser(user.id, guildId);
        const newXp = Math.max(0, currentData.xp - amount);
        const result = dbService.setXp(user.id, guildId, newXp);
        return interaction.reply({
          embeds: [successEmbed(`**${user.tag}** kullan\u0131c\u0131s\u0131ndan **${amount.toLocaleString("tr-TR")} XP** silindi.
Yeni Seviye: \`${result.newLevel}\` (Kalan: \`${result.user.xp.toLocaleString("tr-TR")} XP\`)`)]
        });
      } else if (subcommand === "s\u0131f\u0131rla") {
        dbService.updateUser(user.id, guildId, { xp: 0, level: 1 });
        return interaction.reply({
          embeds: [successEmbed(`**${user.tag}** kullan\u0131c\u0131s\u0131n\u0131n XP ve seviyesi s\u0131f\u0131rland\u0131.`)]
        });
      }
    } catch (error) {
      return interaction.reply({ embeds: [errorEmbed()], flags: MessageFlags78.Ephemeral });
    }
  }
};
var xp_default = xpCommand;

// src/commands/seviye/xp-boost.ts
import {
  MessageFlags as MessageFlags79,
  EmbedBuilder as EmbedBuilder44,
  PermissionFlagsBits as PermissionFlagsBits52,
  SlashCommandBuilder as SlashCommandBuilder92
} from "discord.js";
var xpBoostCommand = {
  data: new SlashCommandBuilder92().setName("xp-boost").setDescription("\u26A1 Belirli rollere veya t\xFCm sunucuya XP \xE7arpan\u0131 (1.5x, 2x) tan\u0131mlay\u0131n").setDefaultMemberPermissions(PermissionFlagsBits52.ManageGuild).addSubcommand(
    (sub) => sub.setName("rol-ekle").setDescription("Bir role \xF6zel XP Boost \xE7arpan\u0131 tan\u0131mlar").addRoleOption(
      (opt) => opt.setName("rol").setDescription("XP Boost verilecek rol (\xD6rn: @VIP, @Booster)").setRequired(true)
    ).addNumberOption(
      (opt) => opt.setName("\xE7arpan").setDescription("Kazan\u0131lacak XP \xE7arpan\u0131 (\xD6rn: 1.5 veya 2.0)").setRequired(true).setMinValue(1.1).setMaxValue(5)
    )
  ).addSubcommand(
    (sub) => sub.setName("rol-sil").setDescription("Bir rolden XP Boost \xE7arpan\u0131n\u0131 kald\u0131r\u0131r").addRoleOption(
      (opt) => opt.setName("rol").setDescription("XP Boost \xE7arpan\u0131 silinecek rol").setRequired(true)
    )
  ).addSubcommand(
    (sub) => sub.setName("sunucu-\xE7arpan\u0131").setDescription("T\xFCm sunucu i\xE7in genel XP \xE7arpan\u0131n\u0131 ayarlar").addNumberOption(
      (opt) => opt.setName("\xE7arpan").setDescription("Genel sunucu \xE7arpan\u0131 (1.0 = normal, 2.0 = 2 kat\u0131)").setRequired(true).setMinValue(0.5).setMaxValue(10)
    )
  ).addSubcommand(
    (sub) => sub.setName("liste").setDescription("Sunucudaki aktif XP Boost rollerini ve \xE7arpanlar\u0131n\u0131 listeler")
  ),
  category: "Seviye",
  cooldown: 5,
  async execute(interaction) {
    if (!interaction.guildId || !interaction.guild) return;
    const sub = interaction.options.getSubcommand();
    const guildId = interaction.guildId;
    const guildConfig = dbService.getGuild(guildId);
    let boostRoles = [];
    try {
      if (guildConfig.xp_boost_roles) {
        boostRoles = JSON.parse(guildConfig.xp_boost_roles);
      }
    } catch {
    }
    if (sub === "rol-ekle") {
      const role = interaction.options.getRole("rol", true);
      const multiplier = interaction.options.getNumber("\xE7arpan", true);
      boostRoles = boostRoles.filter((r) => r.roleId !== role.id);
      boostRoles.push({ roleId: role.id, multiplier });
      dbService.updateGuild(guildId, {
        xp_boost_roles: JSON.stringify(boostRoles)
      });
      const embed = new EmbedBuilder44().setColor("#F1C40F").setTitle("\u26A1 Rol XP Boost \xC7arpan\u0131 Tan\u0131mland\u0131!").setDescription(
        `\`\`\`prolog
\u250C\u2500\u2500 [ XP BOOST YAPILANDIRMASI ] \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510
\u2502 Hedef Rol  : ${role.name.padEnd(27)} \u2502
\u2502 XP \xC7arpan\u0131 : ${(multiplier.toFixed(1) + "x Kat XP").padEnd(27)} \u2502
\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518
\`\`\`
\u2728 Art\u0131k <@&${role.id}> rol\xFCne sahip \xFCyeler mesaj yazd\u0131klar\u0131nda veya seste kald\u0131klar\u0131nda **${multiplier}x** kat\u0131 XP kazanacakt\u0131r!`
      ).setFooter({ text: "Vega XP Boost Motoru" }).setTimestamp();
      return interaction.reply({ embeds: [embed] });
    }
    if (sub === "rol-sil") {
      const role = interaction.options.getRole("rol", true);
      boostRoles = boostRoles.filter((r) => r.roleId !== role.id);
      dbService.updateGuild(guildId, {
        xp_boost_roles: JSON.stringify(boostRoles)
      });
      return interaction.reply({
        content: `\u2705 <@&${role.id}> rol\xFC i\xE7in XP Boost \xE7arpan\u0131 kald\u0131r\u0131ld\u0131.`,
        flags: MessageFlags79.Ephemeral
      });
    }
    if (sub === "sunucu-\xE7arpan\u0131") {
      const mult = interaction.options.getNumber("\xE7arpan", true);
      dbService.updateGuild(guildId, {
        xp_multiplier: mult
      });
      return interaction.reply({
        content: `\u{1F31F} Sunucu geneli taban XP \xE7arpan\u0131 **${mult}x** olarak ayarland\u0131!`,
        flags: MessageFlags79.Ephemeral
      });
    }
    if (sub === "liste") {
      const serverMult = guildConfig.xp_multiplier || 1;
      let text = `\u{1F310} **Genel Sunucu \xC7arpan\u0131:** \`${serverMult}x\`

`;
      if (boostRoles.length === 0) {
        text += "*Bu sunucuda \xF6zel rollere tan\u0131ml\u0131 bir XP Boost bulunmuyor.*";
      } else {
        text += "**\xD6zel Rol \xC7arpanlar\u0131:**\n" + boostRoles.map((b) => `\u2022 <@&${b.roleId}>: \`${b.multiplier}x Boost\``).join("\n");
      }
      const embed = new EmbedBuilder44().setColor("#9B59B6").setTitle(`\u26A1 ${interaction.guild.name} \u2022 XP Boost Listesi`).setDescription(text).setFooter({ text: "Vega Seviye Mod\xFCl\xFC" }).setTimestamp();
      return interaction.reply({ embeds: [embed] });
    }
  }
};
var xp_boost_default = xpBoostCommand;

