import {
  MessageFlags as MessageFlags84,
  SlashCommandBuilder as SlashCommandBuilder97,
  PermissionFlagsBits as PermissionFlagsBits54
} from "discord.js";
var rolHerkeseCommand = {
  data: new SlashCommandBuilder97().setName("rol-herkese").setDescription("Sunucudaki t\xFCm \xFCyelere belirlenen rol\xFC toplu olarak verir").addRoleOption(
    (opt) => opt.setName("rol").setDescription("T\xFCm \xFCyelere verilecek rol").setRequired(true)
  ).addBooleanOption(
    (opt) => opt.setName("botlar_dahil").setDescription("Botlara da verilsin mi? (Varsay\u0131lan: Hay\u0131r)").setRequired(false)
  ).setDefaultMemberPermissions(PermissionFlagsBits54.Administrator),
  category: "rol",
  cooldown: 10,
  async execute(interaction) {
    let deferred = false;
    try {
      const guild = interaction.guild;
      if (!guild) {
        return interaction.reply({
          content: "Bu komut yaln\u0131zca sunucularda kullan\u0131labilir.",
          flags: MessageFlags84.Ephemeral
        });
      }
      const role = interaction.options.getRole("rol", true);
      const includeBots = interaction.options.getBoolean("botlar_dahil") ?? false;
      await interaction.deferReply();
      deferred = true;
      const members = await guild.members.fetch();
      let assigned = 0;
      let failed = 0;
      for (const [, member] of members) {
        if (!includeBots && member.user.bot) continue;
        if (member.roles.cache.has(role.id)) continue;
        try {
          await member.roles.add(role, "Toplu rol verme komutu");
          assigned += 1;
        } catch {
          failed += 1;
        }
      }
      if (failed === 0) {
        return interaction.editReply({
          content: `\u2705 ${role} rol\xFC t\xFCm \xFCyelere ba\u015Far\u0131yla verildi.`
        });
      }
      logger.warn(
        `Toplu rol verme k\u0131smi tamamland\u0131: rol=${role.id}, verildi=${assigned}, hata=${failed}`,
        "Role"
      );
      return interaction.editReply({
        content: assigned > 0 ? `\u26A0\uFE0F ${role} rol\xFC ${assigned} \xFCyeye verildi; ${failed} \xFCyeye verilemedi.` : `\u274C ${role} rol\xFC hi\xE7bir \xFCyeye verilemedi (${failed} hata).`
      });
    } catch (error) {
      logger.error("rol-herkese hatas\u0131", error, "Role");
      const errorMessage = "Rol da\u011F\u0131t\u0131m\u0131 tamamlanamad\u0131. Bot izinlerini ve \xFCye eri\u015Fimini kontrol edin.";
      return deferred ? interaction.editReply({ content: errorMessage }) : interaction.reply({ content: errorMessage, flags: MessageFlags84.Ephemeral });
    }
  }
};
