import {
  MessageFlags as MessageFlags85,
  SlashCommandBuilder as SlashCommandBuilder98,
  PermissionFlagsBits as PermissionFlagsBits55
} from "discord.js";

// src/utils/bulkRoleRemoval.ts
async function removeRoleFromMembers(members, options, concurrency = 4) {
  const eligible = [];
  let totalWithRole = 0;
  let blocked = 0;
  for (const member of members) {
    if (!options.hasRole(member)) continue;
    totalWithRole += 1;
    if (!options.canRemove(member)) {
      blocked += 1;
      continue;
    }
    eligible.push(member);
  }
  let removed = 0;
  let failed = 0;
  let nextIndex = 0;
  const workerCount = Math.min(eligible.length, Math.max(1, Math.floor(concurrency) || 1));
  await Promise.all(Array.from({ length: workerCount }, async () => {
    while (nextIndex < eligible.length) {
      const member = eligible[nextIndex++];
      try {
        await options.remove(member);
        removed += 1;
      } catch {
        failed += 1;
      }
    }
  }));
  return { totalWithRole, removed, blocked, failed };
}

// src/commands/rol/rol-herkesten-al.ts
var rolHerkestenAlCommand = {
  data: new SlashCommandBuilder98().setName("rol-herkesten-al").setDescription("Sunucudaki t\xFCm \xFCyelerden belirlenen rol\xFC toplu olarak al\u0131r").addRoleOption(
    (opt) => opt.setName("rol").setDescription("Herkesten al\u0131nacak rol").setRequired(true)
  ).setDefaultMemberPermissions(PermissionFlagsBits55.ManageRoles),
  category: "rol",
  cooldown: 10,
  async execute(interaction) {
    let deferred = false;
    try {
      const guild = interaction.guild;
      if (!guild) {
        return interaction.reply({
          content: "Bu komut yaln\u0131zca sunucularda kullan\u0131labilir.",
          flags: MessageFlags85.Ephemeral
        });
      }
      const invoker = interaction.member;
      const canManageRoles = invoker?.permissions?.has(PermissionFlagsBits55.ManageRoles) || invoker?.permissions?.has(PermissionFlagsBits55.Administrator) || guild.ownerId === interaction.user.id;
      if (!canManageRoles) {
        return interaction.reply({
          content: "Bu i\u015Flem i\xE7in Rolleri Y\xF6net izni gerekir.",
          flags: MessageFlags85.Ephemeral
        });
      }
      const role = interaction.options.getRole("rol", true);
      await interaction.deferReply({ flags: MessageFlags85.Ephemeral });
      deferred = true;
      if (role.id === guild.id || role.managed) {
        return interaction.editReply({ content: "Bu rol \xFCyelerden al\u0131namaz." });
      }
      const botMember = guild.members.me || await guild.members.fetchMe();
      if (!botMember.permissions.has(PermissionFlagsBits55.ManageRoles)) {
        return interaction.editReply({ content: "Botta Rolleri Y\xF6net izni bulunmuyor." });
      }
      if (role.comparePositionTo(botMember.roles.highest) >= 0) {
        return interaction.editReply({
          content: "Botun en y\xFCksek rol\xFC, se\xE7ilen rolden yukar\u0131da olmal\u0131d\u0131r."
        });
      }
      const members = await guild.members.fetch();
      const result = await removeRoleFromMembers(members.values(), {
        hasRole: (member) => member.roles.cache.has(role.id),
        canRemove: (member) => member.id !== guild.ownerId && (member.id === botMember.id || member.roles.highest.comparePositionTo(botMember.roles.highest) < 0),
        remove: (member) => member.roles.remove(role, "Toplu rol alma komutu")
      }, 4);
      const unsuccessful = result.blocked + result.failed;
      if (unsuccessful === 0) {
        return interaction.editReply({ content: `\u2705 ${role} rol\xFC t\xFCm \xFCyelerden al\u0131nd\u0131.` });
      }
      logger.warn(
        `Toplu rol alma k\u0131smi tamamland\u0131: rol=${role.id}, kald\u0131r\u0131ld\u0131=${result.removed}, engellendi=${result.blocked}, hata=${result.failed}`,
        "Role"
      );
      return interaction.editReply({
        content: `\u2705 ${role} rol\xFC ${result.removed} \xFCyeden al\u0131nd\u0131; ${unsuccessful} \xFCyeden al\u0131namad\u0131 (rol hiyerar\u015Fisi veya Discord hatas\u0131).`
      });
    } catch (error) {
      logger.error("rol-herkesten-al hatas\u0131", error, "Role");
      const errorMessage = "Rol kald\u0131rma i\u015Flemi tamamlanamad\u0131. Bot izinlerini ve \xFCye eri\u015Fimini kontrol edin.";
      return deferred ? interaction.editReply({ content: errorMessage }) : interaction.reply({ content: errorMessage, flags: MessageFlags85.Ephemeral });
    }
  }
};
var rol_herkesten_al_default = rolHerkestenAlCommand;

