// src/utils/ticketTranscript.ts
var MAX_TRANSCRIPT_MESSAGES = 5e3;
async function fetchTicketMessages(channel) {
  const all = [];
  let before;
  let truncated = false;
  while (all.length < MAX_TRANSCRIPT_MESSAGES) {
    const remaining = MAX_TRANSCRIPT_MESSAGES - all.length;
    const batch = await channel.messages.fetch({
      limit: Math.min(100, remaining),
      ...before ? { before } : {}
    });
    if (batch.size === 0) break;
    const page = [...batch.values()];
    all.push(...page);
    before = page.reduce(
      (oldest, message) => !oldest || message.createdTimestamp < oldest.createdTimestamp ? message : oldest,
      null
    )?.id;
    if (batch.size < Math.min(100, remaining)) break;
    if (all.length >= MAX_TRANSCRIPT_MESSAGES) truncated = true;
  }
  all.sort((a, b) => a.createdTimestamp - b.createdTimestamp);
  return { messages: all, truncated };
}
function escapeTranscriptHtml(value) {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

