      if (!targetChannel || !targetChannel.isTextBased()) {
        return interaction.reply({ embeds: [errorEmbed("Ge\xE7erli bir metin kanal\u0131 bulunamad\u0131.", "KANAL BULUNAMADI")], flags: MessageFlags100.Ephemeral });
      }
      const question = interaction.options.getString("soru", true);
      const options = [];
      for (let i = 1; i <= 5; i++) {
        const val = interaction.options.getString(`secenek_${i}`);
        if (val) options.push(val.trim());
      }
