var ozelKomutCommand = {
  data: new SlashCommandBuilder112().setName("\xF6zel-komut").setDescription("\u26A1 Sunucunuza \xF6zel komut ekler, siler veya listeler (Faz 15)").addSubcommand(
    (sub) => sub.setName("ekle").setDescription("Yeni bir \xF6zel komut ekler").addStringOption(
      (opt) => opt.setName("isim").setDescription("Komut ad\u0131 (\xD6rn: kurallar, instagram, sunucu)").setRequired(true)
    ).addStringOption(
      (opt) => opt.setName("yan\u0131t").setDescription("Komut yan\u0131t\u0131 ({kullan\u0131c\u0131}, {sunucu}, {\xFCyesay\u0131s\u0131}, {tarih}, {kanal})").setRequired(true)
    ).addBooleanOption(
      (opt) => opt.setName("embed").setDescription("Yan\u0131t \u015F\u0131k bir embed kart\u0131 olarak m\u0131 g\xF6nderilsin?").setRequired(false)
    )
  ).addSubcommand(
    (sub) => sub.setName("d\xFCzenle").setDescription("Mevcut bir \xF6zel komutun yan\u0131t\u0131n\u0131 veya bi\xE7imini g\xFCnceller").addStringOption(
      (opt) => opt.setName("isim").setDescription("D\xFCzenlenecek komut ad\u0131").setRequired(true)
    ).addStringOption(
      (opt) => opt.setName("yeni-yan\u0131t").setDescription("Yeni komut yan\u0131t\u0131 ({kullan\u0131c\u0131}, {sunucu}, {\xFCye_say\u0131s\u0131}, {tarih}, {kanal})").setRequired(true)
    ).addBooleanOption(
      (opt) => opt.setName("embed").setDescription("Yan\u0131t \u015F\u0131k bir embed kart\u0131 olarak m\u0131 g\xF6nderilsin?").setRequired(false)
    )
  ).addSubcommand(
    (sub) => sub.setName("sil").setDescription("Mevcut bir \xF6zel komutu siler").addStringOption(
      (opt) => opt.setName("isim").setDescription("Silinecek \xF6zel komut ad\u0131").setRequired(true)
    )
  ).addSubcommand(
    (sub) => sub.setName("liste").setDescription("Sunucuda tan\u0131ml\u0131 t\xFCm \xF6zel komutlar\u0131 listeler")
  ).setDefaultMemberPermissions(PermissionFlagsBits68.ManageGuild),
  category: "\xD6zel Komut",
  cooldown: 5,
  async execute(interaction) {
    try {
      const subcommand = interaction.options.getSubcommand();
      const guildId = interaction.guildId;
      if (subcommand === "ekle" || subcommand === "d\xFCzenle") {
        const name = interaction.options.getString("isim", true).toLowerCase().replace(/[^a-z0-9_-]/g, "");
        const response = interaction.options.getString("yan\u0131t") || interaction.options.getString("yeni-yan\u0131t");
        const isEmbed = interaction.options.getBoolean("embed") || false;
        if (!name) {
          return interaction.reply({ embeds: [errorEmbed("Ge\xE7ersiz komut ad\u0131!")], flags: MessageFlags101.Ephemeral });
        }
        dbService.addCustomCommand(guildId, name, response, interaction.user.id, isEmbed);
        return interaction.reply({
          embeds: [
            successEmbed(
              `\`!${name}\` \xF6zel komutu ba\u015Far\u0131yla ${subcommand === "d\xFCzenle" ? "g\xFCncellendi" : "kaydedildi"}!

\u2022 **Yan\u0131t T\xFCr\xFC:** ${isEmbed ? "\u{1F3A8} Embed Mesaj\u0131" : "\u{1F4AC} D\xFCz Metin"}
\u2022 **\xD6nizleme:** ${response}

*\u0130pucu: Yan\u0131t\u0131n\u0131zda \`{kullan\u0131c\u0131}\`, \`{sunucu}\`, \`{\xFCye_say\u0131s\u0131}\`, \`{tarih}\`, \`{kanal}\` de\u011Fi\u015Fkenlerini kullanabilirsiniz.*`
            )
          ]
        });
      } else if (subcommand === "sil") {
        const name = interaction.options.getString("isim", true).toLowerCase();
        const success = dbService.deleteCustomCommand(guildId, name);
        if (!success) {
          return interaction.reply({
            embeds: [errorEmbed(`\`!${name}\` ad\u0131nda bir \xF6zel komut bulunamad\u0131.`)],
            flags: MessageFlags101.Ephemeral
          });
        }
        return interaction.reply({
          embeds: [successEmbed(`\`!${name}\` \xF6zel komutu ba\u015Far\u0131yla silindi.`)]
        });
      } else if (subcommand === "liste") {
        const commands = dbService.getCustomCommands(guildId);
        if (commands.length === 0) {
          return interaction.reply({
            embeds: [createEmbed("\u26A1 \xD6zel Komutlar", "Bu sunucuda hen\xFCz tan\u0131mlanm\u0131\u015F bir \xF6zel komut bulunmuyor.")]
          });
        }
        let desc = `Bu sunucuda toplam **${commands.length}** \xF6zel komut bulunuyor:

`;
        commands.forEach((cmd) => {
          const typeBadge = cmd.is_embed ? "`[Embed]`" : "`[Metin]`";
          desc += `\u2022 \`!${cmd.name}\` ${typeBadge} \u2794 ${cmd.response.slice(0, 50)}${cmd.response.length > 50 ? "..." : ""}
`;
        });
        return interaction.reply({ embeds: [createEmbed("\u26A1 Sunucu \xD6zel Komutlar\u0131", desc)] });
      }
    } catch (error) {
      return interaction.reply({ embeds: [errorEmbed()], flags: MessageFlags101.Ephemeral });
    }
  }
};
var ozel_komut_default = ozelKomutCommand;

