async function generateCoinCanvas(result) {
  const canvas = createCanvas2(350, 180);
  const ctx = canvas.getContext("2d");
  const bgGrad = ctx.createLinearGradient(0, 0, 350, 180);
  bgGrad.addColorStop(0, "#1A0B2E");
  bgGrad.addColorStop(1, "#11052C");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, 350, 180);
  const centerX = 175;
  const centerY = 90;
  const radius = 60;
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius + 5, 0, 2 * Math.PI);
  ctx.fillStyle = "#B8860B";
  ctx.fill();
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, 2 * Math.PI);
  ctx.fillStyle = "#FFD700";
  ctx.fill();
  ctx.lineWidth = 4;
  ctx.strokeStyle = "#FFFFFF";
  ctx.stroke();
  ctx.fillStyle = "#11052C";
  ctx.font = "bold 24px Sans-Serif";
  ctx.textAlign = "center";
  ctx.fillText(result === "YAZI" ? "\u{1FA99} YAZI" : "\u{1F451} TURA", centerX, centerY + 8);
  return canvas.toBuffer("image/png");
}
