// src/commands/eglence/evlilik-cuzdani.ts
import {
  MessageFlags as MessageFlags119,
  EmbedBuilder as EmbedBuilder72,
  SlashCommandBuilder as SlashCommandBuilder132
} from "discord.js";
var evlilikCuzdaniCommand = {
  data: new SlashCommandBuilder132().setName("evlilik-cuzdani").setDescription("\u{1F4DC} Evlilik c\xFCzdan\u0131n\u0131z\u0131, 1./2./3. e\u015Flerinizi ve a\u015Fk istatistiklerinizi g\xF6r\xFCnt\xFCleyin").addUserOption(
    (opt) => opt.setName("kullanici").setDescription("Evlilik c\xFCzdan\u0131n\u0131 g\xF6rmek istedi\u011Finiz kullan\u0131c\u0131 (Bo\u015F b\u0131rak\u0131l\u0131rsa sizinki g\xF6sterilir)").setRequired(false)
  ),
  category: "E\u011Flence",
  cooldown: 5,
  async execute(interaction) {
    try {
      const guild = interaction.guild;
      if (!guild) return;
      const target = interaction.options.getUser("kullanici") || interaction.user;
      const marriages = dbService.getMarriages(guild.id, target.id);
      if (!marriages || marriages.length === 0) {
        const isSelf = target.id === interaction.user.id;
        return interaction.reply({
          embeds: [
            errorEmbed(
              isSelf ? "Hen\xFCz hi\xE7 evli de\u011Filsiniz!\n\n\u{1F48D} Birine evlilik teklifi etmek i\xE7in: `.evlen @kullanici`\n*(1., 2. ve 3. e\u015F yuvalar\u0131n\u0131z bo\u015Ftur)*" : `<@${target.id}> \u015Fu anda kimseyle evli de\u011Fil.`,
              "EVL\u0130L\u0130K KAYDI BULUNAMADI"
            )
          ],
          flags: MessageFlags119.Ephemeral
        });
      }
      const slotNames = {
        1: "\u{1F947} 1. E\u015F (\u0130lk G\xF6z A\u011Fr\u0131s\u0131)",
        2: "\u{1F948} 2. E\u015F (\u0130kinci A\u015Fk)",
        3: "\u{1F949} 3. E\u015F (\xDC\xE7\xFCnc\xFC G\xF6zde)"
      };
      const fieldsData = [];
      for (let i = 0; i < marriages.length; i++) {
        const m = marriages[i];
        const spouseId = m.user1_id === target.id ? m.user2_id : m.user1_id;
        const spouseUser = await interaction.client.users.fetch(spouseId).catch(() => null);
        const slotNum = m.user1_id === target.id ? m.user1_slot || i + 1 : m.user2_slot || i + 1;
        const slotTitle = slotNames[slotNum] || `${slotNum}. E\u015F`;
        const diffMs = Date.now() - m.married_at;
        const days = Math.floor(diffMs / (1e3 * 60 * 60 * 24));
        const hours = Math.floor(diffMs % (1e3 * 60 * 60 * 24) / (1e3 * 60 * 60));
        const loveBarLength = 8;
        const filledBars = Math.min(loveBarLength, Math.floor(m.love_points / 25));
        const emptyBars = Math.max(0, loveBarLength - filledBars);
        const loveBar = "\u{1F496}".repeat(filledBars) + "\u{1F5A4}".repeat(emptyBars);
        const lovePercent = Math.min(100, Math.floor(m.love_points / 2));
        fieldsData.push({
          name: `\u2501\u2501\u2501 ${slotTitle} \u2501\u2501\u2501`,
          value: `\u{1F48D} **E\u015F:** <@${spouseId}> (${spouseUser ? spouseUser.username : "Bilinmiyor"})
\u{1F48E} **Y\xFCz\xFCk:** ${m.ring_type}
\u23F3 **Birliktelik:** ${days} G\xFCn, ${hours} Saat
\u{1F4C5} **Nikah Tarihi:** ${new Date(m.married_at).toLocaleDateString("tr-TR")}
\u{1F496} **A\u015Fk Durumu:** ${loveBar} **(%${lovePercent})** [${m.love_points}/200 Puan]
\u{1F194} **Kay\u0131t ID:** #${m.id}`,
          inline: false
        });
      }
      const walletEmbed = new EmbedBuilder72().setColor("#E91E63").setAuthor({
        name: `T\xDCRK\u0130YE CUMHUR\u0130YET\u0130 \u2022 ULUSLARARASI A\u0130LE C\xDCZDANI`,
        iconURL: "https://cdn.discordapp.com/emojis/1053283162153689149.gif?size=96&quality=lossless"
      }).setTitle(`\u{1F4D5} \u27E6 RESM\u0130 SANAL EVL\u0130L\u0130K C\xDCZDANI \u27E7`).setThumbnail(target.displayAvatarURL()).setDescription(
        `>>> \u{1F464} **C\xFCzdan Sahibi:** <@${target.id}>
\u{1F492} **Aktif Evlilik Say\u0131s\u0131:** **${marriages.length} / 3 Yuva Dolu**

A\u015Fa\u011F\u0131da aktif evlilik kay\u0131tlar\u0131 ve sevgi puan\u0131 durumlar\u0131 listelenmi\u015Ftir:`
      ).addFields(fieldsData).setFooter({ text: "Vega Evlilik Sistemi \u2022 Sevgi puan\u0131 art\u0131rmak i\xE7in: /hediye-et veya /sev" }).setTimestamp();
      return interaction.reply({ embeds: [walletEmbed] });
    } catch (err) {
      if (interaction.deferred || interaction.replied) {
        await interaction.editReply({ content: "\u274C C\xFCzdan a\xE7\u0131l\u0131rken bir hata olu\u015Ftu." }).catch(() => null);
      } else {
        await interaction.reply({ content: "\u274C C\xFCzdan a\xE7\u0131l\u0131rken bir hata olu\u015Ftu.", flags: MessageFlags119.Ephemeral }).catch(() => null);
      }
    }
  }
};
var evlilik_cuzdani_default = evlilikCuzdaniCommand;

