            const cell = board[r][c];
            const btn = new ButtonBuilder43().setCustomId(`mine_${r}_${c}`);
            if (cell.revealed || gameOver) {
              btn.setDisabled(true);
              if (cell.isMine) {
                btn.setLabel("\u{1F4A3}").setStyle(ButtonStyle43.Danger);
              } else {
                btn.setLabel(cell.adjacent > 0 ? cell.adjacent.toString() : "\u{1F7E9}").setStyle(ButtonStyle43.Success);
              }
            } else {
              btn.setLabel("\u{1F7E6}").setStyle(ButtonStyle43.Secondary);
            }
