async function generateDiceCanvas(p1Name, d1, p2Name, d2) {
  const canvas = createCanvas3(500, 240);
  const ctx = canvas.getContext("2d");
  const bgGrad = ctx.createLinearGradient(0, 0, 500, 240);
  bgGrad.addColorStop(0, "#1A1C29");
  bgGrad.addColorStop(1, "#0D0E15");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, 500, 240);
  ctx.strokeStyle = "#9B59B6";
  ctx.lineWidth = 5;
  ctx.strokeRect(10, 10, 480, 220);
  ctx.fillStyle = "#FFD700";
  ctx.font = "bold 22px Sans-Serif";
  ctx.textAlign = "center";
  ctx.fillText("\u{1F3B2} SAVA\u015E ZARLARI M\xDCCADELES\u0130 \u{1F3B2}", 250, 40);
  ctx.fillStyle = "#16213E";
  ctx.fillRect(30, 60, 190, 140);
  ctx.strokeStyle = "#3498DB";
  ctx.lineWidth = 3;
  ctx.strokeRect(30, 60, 190, 140);
  ctx.fillStyle = "#FFFFFF";
  ctx.font = "bold 16px Sans-Serif";
  ctx.fillText(p1Name.substring(0, 12), 125, 90);
  ctx.fillStyle = "#3498DB";
  ctx.font = "bold 50px Sans-Serif";
  ctx.fillText(`\u{1F3B2} ${d1}`, 125, 160);
  ctx.fillStyle = "#E74C3C";
  ctx.font = "bold 24px Sans-Serif";
  ctx.fillText("VS", 250, 135);
  ctx.fillStyle = "#16213E";
  ctx.fillRect(280, 60, 190, 140);
  ctx.strokeStyle = "#E74C3C";
  ctx.lineWidth = 3;
  ctx.strokeRect(280, 60, 190, 140);
  ctx.fillStyle = "#FFFFFF";
  ctx.font = "bold 16px Sans-Serif";
  ctx.fillText(p2Name.substring(0, 12), 375, 90);
  ctx.fillStyle = "#E74C3C";
  ctx.font = "bold 50px Sans-Serif";
  ctx.fillText(`\u{1F3B2} ${d2}`, 375, 160);
  return canvas.toBuffer("image/png");
}
