var SLOT_SYMBOLS = ["\u{1F352}", "\u{1F34B}", "\u{1F34A}", "\u{1F347}", "\u{1F48E}", "7\uFE0F\u20E3"];
async function generateSlotCanvas(reels, bet, winAmount) {
  const canvas = createCanvas4(450, 220);
  const ctx = canvas.getContext("2d");
  const bgGrad = ctx.createLinearGradient(0, 0, 450, 220);
  bgGrad.addColorStop(0, "#1A0B2E");
  bgGrad.addColorStop(1, "#2D0B5A");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, 450, 220);
  ctx.strokeStyle = "#9B59B6";
  ctx.lineWidth = 6;
  ctx.strokeRect(10, 10, 430, 200);
  ctx.fillStyle = "#F1C40F";
  ctx.font = "bold 22px Sans-Serif";
  ctx.textAlign = "center";
  ctx.fillText("\u{1F3B0} VEGA VEGAS SLOT \u{1F3B0}", 225, 42);
  const boxWidth = 110;
  const boxHeight = 100;
  const startX = 40;
  const startY = 60;
  const gap = 20;
  for (let i = 0; i < 3; i++) {
    const x = startX + i * (boxWidth + gap);
    ctx.fillStyle = "#0F051D";
    ctx.fillRect(x, startY, boxWidth, boxHeight);
    ctx.strokeStyle = "#E91E63";
    ctx.lineWidth = 3;
    ctx.strokeRect(x, startY, boxWidth, boxHeight);
    ctx.fillStyle = "#FFFFFF";
    ctx.font = "50px Sans-Serif";
    ctx.textAlign = "center";
    ctx.fillText(reels[i], x + boxWidth / 2, startY + 70);
  }
  ctx.fillStyle = winAmount > 0 ? "#2ECC71" : "#E74C3C";
  ctx.font = "bold 18px Sans-Serif";
  ctx.textAlign = "center";
  const statusText = winAmount > 0 ? `\u{1F389} KAZANDIN: +${winAmount} COIN!` : `\u{1F494} KAYBETT\u0130N: -${bet} COIN`;
  ctx.fillText(statusText, 225, 190);
  return canvas.toBuffer("image/png");
}
