import { createCanvas as createCanvas6 } from "@napi-rs/canvas";
async function createFallbackArt(prompt, artist) {
  const canvas = createCanvas6(768, 512);
  const ctx = canvas.getContext("2d");
  const grad = ctx.createLinearGradient(0, 0, 768, 512);
  grad.addColorStop(0, "#0F0C20");
  grad.addColorStop(0.5, "#2D1152");
  grad.addColorStop(1, "#6C3483");
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 768, 512);
  ctx.strokeStyle = "#9B59B6";
  ctx.lineWidth = 4;
  ctx.strokeRect(30, 30, 708, 452);
  ctx.fillStyle = "#F1C40F";
  ctx.font = "bold 28px Sans-Serif";
  ctx.textAlign = "center";
  ctx.fillText("\u{1F3A8} VEGA AI VISUAL STUDIO \u{1F3A8}", 384, 80);
  ctx.fillStyle = "#FFFFFF";
  ctx.font = "italic 20px Sans-Serif";
  const displayPrompt = prompt.length > 70 ? prompt.slice(0, 67) + "..." : prompt;
  ctx.fillText(`"${displayPrompt}"`, 384, 220);
  ctx.fillStyle = "#3498DB";
  ctx.font = "16px Sans-Serif";
  ctx.fillText(`\u0130stem Sahibi: ${artist}`, 384, 300);
  return canvas.toBuffer("image/png");
}
