import { EmbedBuilder as EmbedBuilder107, SlashCommandBuilder as SlashCommandBuilder176, AttachmentBuilder as AttachmentBuilder14 } from "discord.js";
import { createCanvas as createCanvas7 } from "@napi-rs/canvas";
import { GoogleGenAI as GoogleGenAI2 } from "@google/genai";
async function generateArtificialArtCanvas(prompt, artistName) {
  const canvas = createCanvas7(600, 350);
  const ctx = canvas.getContext("2d");
  const bgGrad = ctx.createLinearGradient(0, 0, 600, 350);
  bgGrad.addColorStop(0, "#0F0C20");
  bgGrad.addColorStop(0.5, "#2D1152");
  bgGrad.addColorStop(1, "#4A154B");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, 600, 350);
  const colors2 = ["rgba(155, 89, 182, 0.4)", "rgba(52, 152, 219, 0.4)", "rgba(233, 30, 99, 0.4)", "rgba(241, 196, 15, 0.3)"];
  for (let i = 0; i < 8; i++) {
    ctx.beginPath();
    const rx = Math.random() * 600;
    const ry = Math.random() * 350;
    const rr = Math.random() * 120 + 30;
    ctx.arc(rx, ry, rr, 0, 2 * Math.PI);
    ctx.fillStyle = colors2[i % colors2.length];
    ctx.fill();
  }
  ctx.fillStyle = "rgba(20, 10, 35, 0.75)";
  ctx.fillRect(30, 30, 540, 290);
  ctx.strokeStyle = "#9B59B6";
  ctx.lineWidth = 3;
  ctx.strokeRect(30, 30, 540, 290);
  ctx.fillStyle = "#FFD700";
  ctx.font = "bold 22px Sans-Serif";
  ctx.textAlign = "center";
  ctx.fillText("\u{1F3A8} VEGA AI ART SYNTHESIS \u{1F3A8}", 300, 70);
  ctx.fillStyle = "#FFFFFF";
  ctx.font = "italic 18px Sans-Serif";
  const displayPrompt = prompt.length > 55 ? prompt.substring(0, 52) + "..." : prompt;
  ctx.fillText(`"${displayPrompt}"`, 300, 150);
  ctx.fillStyle = "#3498DB";
  ctx.font = "bold 15px Sans-Serif";
  ctx.fillText(`\u2728 Tasarlayan: ${artistName}`, 300, 230);
  ctx.fillStyle = "#A0A0A0";
  ctx.font = "13px Sans-Serif";
  ctx.fillText("\u26A1 Generated via Gemini & Vega Art Engine", 300, 280);
  return canvas.toBuffer("image/png");
}
