var logAyarlaCommand = {
  data: new SlashCommandBuilder178().setName("log-ayarla").setDescription("\u{1F4DC} Mod, Mesaj, Ses, \xDCye, Rol ve Kanal log kanallar\u0131n\u0131 yap\u0131land\u0131r\u0131r").setDefaultMemberPermissions(PermissionFlagsBits79.Administrator).addStringOption(
    (opt) => opt.setName("t\xFCr").setDescription("Ayar\u0131n\u0131 de\u011Fi\u015Ftirmek istedi\u011Finiz log t\xFCr\xFC").setRequired(true).addChoices(
      { name: "\u{1F528} Mod-Log (Ban, Kick, Mute, Warn)", value: "mod" },
      { name: "\u{1F4AC} Mesaj-Log (Silinen ve D\xFCzenlenen Mesajlar)", value: "mesaj" },
      { name: "\u{1F50A} Ses-Log (Ses Kanal\u0131 Giri\u015F/\xC7\u0131k\u0131\u015F/Ta\u015F\u0131ma)", value: "ses" },
      { name: "\u{1F464} \xDCye-Log (Sunucuya Giri\u015F ve Ayr\u0131lma)", value: "uye" },
      { name: "\u{1F451} Rol-Log (Rol Olu\u015Fturma/Silme/Verme)", value: "rol" },
      { name: "\u{1F4C1} Kanal-Log (Kanal Olu\u015Fturma/Silme/G\xFCncelleme)", value: "kanal" }
    )
  ).addChannelOption(
    (opt) => opt.setName("kanal").setDescription("Loglar\u0131n iletilece\u011Fi metin kanal\u0131 (Bo\u015F b\u0131rak\u0131l\u0131rsa log kapat\u0131l\u0131r)").addChannelTypes(ChannelType32.GuildText).setRequired(false)
  ),
  category: "Log",
  cooldown: 5,
  async execute(interaction) {
    try {
      if (!interaction.guild) return;
      const logType = interaction.options.getString("t\xFCr", true);
      const targetChannel = interaction.options.getChannel("kanal");
      const guildId = interaction.guild.id;
      const updateMap = {
        mod: "mod_log_channel",
        mesaj: "mesaj_log_channel",
        ses: "ses_log_channel",
        uye: "uye_log_channel",
        rol: "rol_log_channel",
        kanal: "kanal_log_channel"
      };
      const typeNames = {
        mod: "Mod-Log (Yetkili \u0130\u015Flemleri)",
        mesaj: "Mesaj-Log (Silinen / D\xFCzenlenen)",
        ses: "Ses-Log (Ses Olaylar\u0131)",
        uye: "\xDCye-Log (Giri\u015F / \xC7\u0131k\u0131\u015F)",
        rol: "Rol-Log (Rol G\xFCncellemeleri)",
        kanal: "Kanal-Log (Kanal De\u011Fi\u015Fiklikleri)"
      };
      const fieldName = updateMap[logType];
      const channelId = targetChannel ? targetChannel.id : null;
      dbService.updateGuild(guildId, {
        [fieldName]: channelId
      });
      const embed = new EmbedBuilder109().setColor(channelId ? "#2ECC71" : "#E74C3C").setTitle("\u{1F4DC} Log Kanal\u0131 G\xFCncellendi").setDescription(
        channelId ? `\u2705 **${typeNames[logType]}** loglar\u0131 art\u0131k <#${channelId}> kanal\u0131na iletilecektir.` : `\u{1F534} **${typeNames[logType]}** log kanal\u0131 kapat\u0131ld\u0131 (s\u0131f\u0131rland\u0131).`
      ).setFooter({ text: "Vega Log & Audit Trail System" }).setTimestamp();
      await interaction.reply({ embeds: [embed] });
    } catch (error) {
      if (interaction.deferred || interaction.replied) {
        await interaction.editReply({ content: "\u274C Bir hata olu\u015Ftu." }).catch(() => null);
      } else {
        await interaction.reply({ content: "\u274C Bir hata olu\u015Ftu.", flags: MessageFlags162.Ephemeral }).catch(() => null);
      }
    }
  }
};
var log_ayarla_default = logAyarlaCommand;

