// src/handlers/commandHandler.ts
function loadCommands(client2) {
  try {
    allCommands.forEach((cmd) => {
      client2.commands.set(cmd.data.name, cmd);
    });
    logger.success(`Toplam ${client2.commands.size} komut ba\u015Far\u0131yla y\xFCklendi.`, "CommandHandler");
  } catch (error) {
    logger.error("Komutlar y\xFCklenirken bir hata olu\u015Ftu", error, "CommandHandler");
  }
}

