import { Collection } from "discord.js";
var cooldowns = new Collection();
function checkCooldown(commandName, userId, cooldownAmount = 3) {
  if (!cooldowns.has(commandName)) {
    cooldowns.set(commandName, new Collection());
  }
  const now = Date.now();
  const timestamps = cooldowns.get(commandName);
  const cooldownMs = cooldownAmount * 1e3;
  if (timestamps.has(userId)) {
    const expirationTime = timestamps.get(userId) + cooldownMs;
    if (now < expirationTime) {
      const timeLeft = (expirationTime - now) / 1e3;
      return Number(timeLeft.toFixed(1));
    }
  }
  timestamps.set(userId, now);
  setTimeout(() => timestamps.delete(userId), cooldownMs);
  return null;
}

