async function handlePrefixCommand(client2, message) {
  message = wrapV2OutgoingEntity(message, message.author);
  if (!message.guild) return false;
  const content = message.content.trim();
  const gConfig = dbService.getGuild(message.guild.id);
  const guildPrefix = gConfig.prefix?.trim() || config.prefix;
  if (!content.startsWith(guildPrefix)) return false;
  const withoutPrefix = content.slice(guildPrefix.length).trim();
  if (!withoutPrefix) return false;
  const firstSpace = withoutPrefix.search(/\s/);
  const rawName = (firstSpace === -1 ? withoutPrefix : withoutPrefix.slice(0, firstSpace)).toLowerCase();
  const rest = firstSpace === -1 ? "" : withoutPrefix.slice(firstSpace + 1).trim();
  const command15 = client2.commands.get(rawName) || client2.commands.find(
    (c) => c.data.name.toLocaleLowerCase("tr-TR") === rawName.toLocaleLowerCase("tr-TR")
  );
  if (!command15) return false;
  const panelCategory = panelCategoryForCommand(command15.category);
  if (panelCategory && !dbService.getGuildCommandToggles(message.guild.id)[panelCategory]) {
    const categoryLabels = { moderation: "Moderasyon", giveaway: "\xC7ekili\u015F", level: "Seviye", music: "M\xFCzik", entertainment: "E\u011Flence" };
    await message.reply({ content: `\u26A0\uFE0F Bu sunucuda ${categoryLabels[panelCategory]} komut grubu devre d\u0131\u015F\u0131.` }).catch(() => null);
    return true;
  }
  if (dbService.getBotSetting("maintenance_mode") === "true" && message.author.id !== BOT_OWNER_ID) {
    await message.reply({ content: "\u{1F6A7} **Vega \u015Fu anda bak\u0131m modundad\u0131r.** Yaln\u0131zca bot sahibi komut \xE7al\u0131\u015Ft\u0131rabilir." }).catch(() => null);
    return true;
  }
  if (gConfig && gConfig.disabled_commands) {
    try {
      const disabled = JSON.parse(gConfig.disabled_commands);
      if (disabled.includes(command15.data.name)) {
        await message.reply({
          content: `\u26A0\uFE0F \`${guildPrefix}${command15.data.name}\` komutu bu sunucuda y\xF6neticiler taraf\u0131ndan devre d\u0131\u015F\u0131 b\u0131rak\u0131lm\u0131\u015Ft\u0131r.`
        }).catch(() => null);
        return true;
      }
    } catch {
    }
  }
  if (STAFF_COMMANDS.has(command15.data.name)) {
    const guild = message.guild;
    const member = message.member;
    const isOwner = guild.ownerId === message.author.id;
    const isBotOwner = message.author.id === config.ownerId || message.author.id === BOT_OWNER_ID;
    const isAdmin = Boolean(member?.permissions?.has(PermissionFlagsBits83.Administrator));
    const staffRoleId = dbService.getStaffRole(guild.id);
    const hasStaffRole = Boolean(staffRoleId && member?.roles?.cache?.has(staffRoleId));
    if (!(isOwner || isBotOwner || isAdmin || hasStaffRole)) {
      await message.reply({ embeds: [errorEmbed("Bu komutu kullanma yetkiniz bulunmuyor.", "YETK\u0130 YETERS\u0130Z")] }).catch(() => null);
      return true;
    }
  }
  try {
    const requiredPerms = command15.data.toJSON().default_member_permissions;
    if (requiredPerms) {
      if (!message.member) throw new Error("Guild member is unavailable");
      const hasPerm = message.member.permissions.has(BigInt(requiredPerms));
      if (!hasPerm) {
        await message.reply({ embeds: [errorEmbed("Bu komutu kullanmak i\xE7in gerekli sunucu yetkiniz bulunmuyor.", "YETK\u0130 YETERS\u0130Z")] }).catch(() => null);
        return true;
      }
    }
  } catch (permissionError) {
    logger.error(`Prefix izin bilgisi \xE7\xF6z\xFCmlenemedi: ${command15.data.name}`, permissionError, "Permissions");
    await message.reply({ embeds: [errorEmbed("Komut izinleri do\u011Frulanamad\u0131; g\xFCvenlik i\xE7in i\u015Flem durduruldu.", "\u0130Z\u0130N DO\u011ERULANAMADI")] }).catch(() => null);
    return true;
  }
  const tokens = tokenizeArgs(rest);
  const parsed = parseCommandArgs(command15, tokens, message);
  if (parsed.missing.length > 0) {
    const usage = buildUsage(command15, guildPrefix);
    const embed = new EmbedBuilder115().setColor("#E74C3C").setTitle(`\u26A0\uFE0F \u27E6 ${command15.data.name.toUpperCase()} \u2022 EKS\u0130K ARG\xDCMAN \u27E7`).setDescription(
      `Eksik parametre(ler): ${parsed.missing.map((m) => `\`${m}\``).join(", ")}

${usage}`
    ).setFooter({ text: "Vega Prefix Sistemi \u2022 Arg\xFCman Rehberi" }).setTimestamp();
    await message.reply({ embeds: [embed] }).catch(() => null);
    return true;
  }
  const cooldownRemaining = checkCooldown(command15.data.name, message.author.id, command15.cooldown || 3);
  if (cooldownRemaining !== null) {
    await message.reply({
      embeds: [errorEmbed(`L\xFCtfen bu komutu tekrar kullanmak i\xE7in \`${cooldownRemaining}s\` bekleyin.`)]
    }).catch(() => null);
    return true;
  }
  try {
    dbService.logCommand(message.guild.id, message.author.id, command15.data.name);
    dbService.recordCommandUsage(message.guild.id, message.author.id, command15.data.name);
  } catch {
  }
  logger.info(
    `Komut kullan\u0131ld\u0131: ${guildPrefix}${command15.data.name} | Kullan\u0131c\u0131: ${message.author.tag} (${message.author.id})`,
    "CommandLog"
  );
  const ctx = new PrefixContext(message, command15, parsed);
  try {
    await command15.execute(ctx);
  } catch (error) {
    logger.error(`Prefix komut hatas\u0131: ${guildPrefix}${command15.data.name}`, error, "Prefix");
    notifyOwnerError(client2, {
      errorType: "Prefix Komut Hatas\u0131",
      commandName: command15.data.name,
      guild: message.guild,
      user: message.author,
      error
    }).catch(() => null);
    const embed = errorEmbed("Komut y\xFCr\xFCt\xFCl\xFCrken beklenmeyen bir hata olu\u015Ftu.");
    try {
      if (ctx.replied) await ctx.followUp({ embeds: [embed] });
      else await ctx.reply({ embeds: [embed] });
    } catch {
      await message.reply({ embeds: [embed] }).catch(() => null);
    }
  }
  return true;
}

// src/utils/tempBanManager.ts
import { EmbedBuilder as EmbedBuilder116 } from "discord.js";
var TempBanManager = class {
  client = null;
  interval = null;
  checking = false;
  init(client2) {
    this.client = client2;
    this.startChecking();
  }
  shutdown() {
    if (this.interval) clearInterval(this.interval);
    this.interval = null;
    this.client = null;
  }
  startChecking() {
    if (this.interval) clearInterval(this.interval);
    this.interval = setInterval(async () => {
      if (this.checking) return;
      this.checking = true;
      try {
        await this.checkExpiredBans();
      } finally {
        this.checking = false;
      }
    }, 60 * 1e3);
  }
  async checkExpiredBans() {
    if (!this.client || !this.client.isReady()) return;
    try {
      const expiredList = dbService.getExpiredTempBans();
      for (const ban of expiredList) {
        const guild = this.client.guilds.cache.get(ban.guild_id);
        if (!guild) {
          dbService.scheduleTempBanRetry(ban.id, Date.now() + 60 * 60 * 1e3);
          continue;
        }
        try {
          await guild.bans.remove(ban.user_id, "Vega S\xFCreli Ban: S\xFCre doldu (Otomatik Unban)");
          dbService.removeTempBan(ban.id);
          const logEmbed = new EmbedBuilder116().setColor("#2ECC71").setTitle("\u{1F513} [S\xFCreli Ban] Kullan\u0131c\u0131 Ban\u0131 A\xE7\u0131ld\u0131").setDescription(`**Kullan\u0131c\u0131 ID:** \`${ban.user_id}\`
**Ban Sebebi:** ${ban.reason}
**\u0130\u015Flem:** S\xFCre tamamland\u0131, otomatik kald\u0131r\u0131ld\u0131.`).setTimestamp();
          sendGuildLog(guild, "mod", logEmbed);
        } catch (unbanErr) {
          if (unbanErr?.code === 10026) {
            dbService.removeTempBan(ban.id);
          } else {
            dbService.scheduleTempBanRetry(ban.id);
            logger.warn(`Temp-ban kald\u0131r\u0131l\u0131rken hata; kay\u0131t retry i\xE7in korunuyor: ID ${ban.user_id}`, "TempBan");
          }
        }
      }
    } catch (err) {
      logger.error("S\xFCreli ban kontrol\xFCnde hata", err, "TempBan");
    }
  }
};
var tempBanManager = new TempBanManager();

