import { createCanvas as createCanvas8 } from "@napi-rs/canvas";
function generateRandomCode(length = 5) {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let code = "";
  for (let i = 0; i < length; i++) {
    code += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return code;
}
function generateCaptcha(length = 5) {
  const width = 300;
  const height = 110;
  const canvas = createCanvas8(width, height);
  const ctx = canvas.getContext("2d");
  const code = generateRandomCode(length);
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#1E1F22");
  bgGrad.addColorStop(1, "#2B2D31");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);
  for (let i = 0; i < 60; i++) {
    ctx.fillStyle = `rgba(${Math.floor(Math.random() * 200 + 55)}, ${Math.floor(Math.random() * 200 + 55)}, ${Math.floor(Math.random() * 200 + 55)}, ${Math.random() * 0.4 + 0.1})`;
    ctx.beginPath();
    ctx.arc(Math.random() * width, Math.random() * height, Math.random() * 3 + 1, 0, Math.PI * 2);
    ctx.fill();
  }
  for (let i = 0; i < 5; i++) {
    ctx.strokeStyle = `rgba(${Math.floor(Math.random() * 150 + 100)}, ${Math.floor(Math.random() * 150 + 100)}, 255, ${Math.random() * 0.5 + 0.3})`;
    ctx.lineWidth = Math.random() * 2 + 1.5;
    ctx.beginPath();
    ctx.moveTo(Math.random() * width, Math.random() * height);
    ctx.bezierCurveTo(
      Math.random() * width,
      Math.random() * height,
      Math.random() * width,
      Math.random() * height,
      Math.random() * width,
      Math.random() * height
    );
    ctx.stroke();
  }
  const charSpacing = (width - 60) / length;
  const colors2 = ["#00B0FF", "#00E676", "#FFD600", "#FF5252", "#E040FB", "#69F0AE"];
  for (let i = 0; i < length; i++) {
    const char = code[i];
    const x = 35 + i * charSpacing;
    const y = 65 + (Math.random() * 14 - 7);
    const angle = (Math.random() * 30 - 15) * (Math.PI / 180);
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.font = "bold 42px sans-serif";
    ctx.fillStyle = colors2[i % colors2.length];
    ctx.shadowColor = "rgba(0, 0, 0, 0.7)";
    ctx.shadowBlur = 6;
    ctx.shadowOffsetX = 2;
    ctx.shadowOffsetY = 2;
    ctx.fillText(char, 0, 0);
    ctx.restore();
  }
  ctx.strokeStyle = "#5865F2";
  ctx.lineWidth = 3;
  ctx.strokeRect(2, 2, width - 4, height - 4);
  return {
    code,
    imageBuffer: canvas.toBuffer("image/png")
  };
}

