      const dmEmbed = new EmbedBuilder121().setColor("#9B59B6").setTitle(`\u2728 ${guild.name} \u2022 Ho\u015F Geldin! \u{1F389}`).setThumbnail(guild.iconURL() || member.user.displayAvatarURL()).setDescription(dmFormatted).setFooter({ text: "Vega DM Kar\u015F\u0131lama Servisi \u{1F4AB}" }).setTimestamp();
