// src/events/messageReactionAdd.ts
import { EmbedBuilder as EmbedBuilder124 } from "discord.js";
async function onMessageReactionAdd(client2, reaction, user) {
  if (user.bot) return;
  if (reaction.partial) {
    try {
      await reaction.fetch();
    } catch {
      return;
    }
  }
  if (reaction.message.partial) {
    try {
      await reaction.message.fetch();
    } catch {
      return;
    }
  }
  if (reaction.emoji.name !== "\u2B50" && reaction.emoji.name !== "\u{1F31F}") {
    return;
  }
  const message = reaction.message;
  if (!message.guild) return;
  const guildConfig = dbService.getGuild(message.guild.id);
  const starboardChannelId = guildConfig.starboard_channel;
  if (!starboardChannelId) return;
  const starLimit = guildConfig.starboard_limit || 3;
  const count = reaction.count || 0;
  if (count < starLimit) return;
  const targetChannel = message.guild.channels.cache.get(starboardChannelId);
  if (!targetChannel || !("send" in targetChannel)) return;
  if (message.channelId === starboardChannelId) return;
  const existingStar = dbService.getStarboardMessage(message.guild.id, message.id);
  const starText = count >= 10 ? `\u{1F4AB} **${count}**` : count >= 5 ? `\u{1F31F} **${count}**` : `\u2B50 **${count}**`;
  const embed = new EmbedBuilder124().setColor("#F1C40F").setAuthor({
    name: message.author?.tag || "Bilinmeyen Kullan\u0131c\u0131",
    iconURL: message.author?.displayAvatarURL() || void 0
  }).setDescription(message.content || "*(G\xF6rsel / Ek dosya)*").addFields(
    {
      name: "Orijinal Mesaj",
      value: `[Mesaja Git](${message.url}) \u2022 Kanal: <#${message.channelId}>`
    }
  ).setFooter({ text: `Mesaj ID: ${message.id}` }).setTimestamp(message.createdAt);
  const attachment = message.attachments.first();
  if (attachment && attachment.contentType?.startsWith("image/")) {
    embed.setImage(attachment.url);
  }
  try {
    if (existingStar) {
      const sbMsg = await targetChannel.messages.fetch(existingStar.starboard_message_id).catch(() => null);
      if (sbMsg) {
        await sbMsg.edit({
          content: `${starText} <#${message.channelId}>`,
          embeds: [embed]
        });
        dbService.updateStarboardStars(message.guild.id, message.id, count);
      }
    } else {
      const sentMsg = await targetChannel.send({
        content: `${starText} <#${message.channelId}>`,
        embeds: [embed]
      });
      dbService.saveStarboardMessage(
        message.guild.id,
        message.id,
        sentMsg.id,
        message.channelId,
        message.author?.id || "",
        count
      );
    }
  } catch (err) {
    logger.error("Starboard mesaj\u0131 g\xF6nderilirken hata", err, "Starboard");
  }
}

// src/events/presenceUpdate.ts
import { ActivityType as ActivityType5 } from "discord.js";
async function handlePresenceUpdate(oldPresence, newPresence) {
  try {
    if (!newPresence.guild || !newPresence.member || newPresence.member.user.bot) return;
    const guildId = newPresence.guild.id;
    const rules = dbService.getStatusRoles(guildId);
    if (!rules || rules.length === 0) return;
    const customActivity = newPresence.activities.find((a) => a.type === ActivityType5.Custom);
    const statusText = (customActivity?.state || "").toLowerCase();
    const member = newPresence.member;
    for (const rule of rules) {
      const keyword = rule.keyword.toLowerCase();
      const hasKeyword = statusText.includes(keyword);
      const hasRole = member.roles.cache.has(rule.role_id);
      if (hasKeyword && !hasRole) {
        try {
          await member.roles.add(rule.role_id, `Durum Rol\xFC: Durumunda "${rule.keyword}" tespit edildi`);
          logger.info(`Durum rol\xFC verildi: ${member.user.tag} -> ${rule.role_id} (Kelime: ${rule.keyword})`, "PresenceUpdate");
        } catch (err) {
          logger.warn(`Durum rol\xFC verilemedi (${member.user.tag}): ${err}`, "PresenceUpdate");
        }
      } else if (!hasKeyword && hasRole) {
        try {
          await member.roles.remove(rule.role_id, `Durum Rol\xFC: Durumundan "${rule.keyword}" kald\u0131r\u0131ld\u0131`);
          logger.info(`Durum rol\xFC al\u0131nd\u0131: ${member.user.tag} -> ${rule.role_id} (Kelime kald\u0131r\u0131ld\u0131)`, "PresenceUpdate");
        } catch (err) {
          logger.warn(`Durum rol\xFC al\u0131namad\u0131 (${member.user.tag}): ${err}`, "PresenceUpdate");
        }
      }
    }
  } catch (error) {
    logger.error("handlePresenceUpdate i\u015Fleminde hata olu\u015Ftu", error, "PresenceUpdate");
  }
}

