// src/events/auditEvents.ts
function formatTurkishDate(date) {
  return date.toLocaleDateString("tr-TR", {
    day: "numeric",
    month: "long",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit"
  });
}
function timeDifferenceText(startMs, endMs) {
  const diffSec = Math.max(1, Math.floor((endMs - startMs) / 1e3));
  if (diffSec < 60) return `${diffSec} saniye sonra`;
  const mins = Math.floor(diffSec / 60);
  if (mins < 60) return `${mins} dakika sonra`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${hours} saat sonra`;
  const days = Math.floor(hours / 24);
  return `${days} g\xFCn sonra`;
}
