// src/handlers/eventHandler.ts
function isHelpInteraction(interaction) {
  if (interaction?.isChatInputCommand?.() && interaction.commandName === "yardim") return true;
  if (interaction?.isButton?.() && typeof interaction.customId === "string" && interaction.customId.startsWith("help_")) return true;
  if (interaction?.isStringSelectMenu?.() && interaction.customId === "help_category_select") return true;
  return false;
}
function runSafely(eventName, action) {
  void Promise.resolve().then(action).catch((error) => logger.error(`${eventName} olay\u0131 i\u015Flenirken hata olu\u015Ftu`, error, "EventHandler"));
}
async function dispatchInteraction(client2, interaction) {
  interaction = wrapV2Interaction(interaction);
  try {
    if (interaction.guildId && !isHelpInteraction(interaction) && isGuardPriorityActive(interaction.guildId)) {
      if (interaction.isRepliable?.() && !interaction.deferred && !interaction.replied) {
        await interaction.reply({
          content: "Sunucu g\xFCvenlik i\u015Flemi s\xFCr\xFCyor. L\xFCtfen birka\xE7 saniye sonra yeniden deneyin.",
          flags: MessageFlags170.Ephemeral
        });
      }
      return;
    }
    await onInteractionCreate(client2, interaction);
  } catch (error) {
    logger.error("InteractionCreate handler ba\u015Far\u0131s\u0131z oldu", error, "EventHandler");
    try {
      if (!interaction.isRepliable?.()) return;
      const payload = {
        content: "\u0130\u015Flem s\u0131ras\u0131nda beklenmeyen bir hata olu\u015Ftu. L\xFCtfen tekrar deneyin.",
        flags: MessageFlags170.Ephemeral
      };
      if (interaction.deferred || interaction.replied) await interaction.followUp(payload);
      else await interaction.reply(payload);
    } catch {
    }
  }
}
function loadEvents(client2) {
  try {
    client2.once(Events.ClientReady, () => runSafely("ClientReady", () => onReady(client2)));
    client2.on(Events.InteractionCreate, (interaction) => {
      void dispatchInteraction(client2, interaction);
    });
    client2.on(Events.MessageCreate, (message) => runSafely("MessageCreate", async () => {
      if (message.guildId) await runAfterGuards(message.guildId, () => onMessageCreate(client2, message));
      else await onMessageCreate(client2, message);
    }));
    client2.on(Events.MessageReactionAdd, (reaction, user) => runSafely("MessageReactionAdd", async () => {
      const guildId = reaction.message.guildId;
      if (guildId) await runAfterGuards(guildId, () => onMessageReactionAdd(client2, reaction, user));
      else await onMessageReactionAdd(client2, reaction, user);
    }));
    client2.on(Events.GuildMemberAdd, (member) => runSafely(
      "GuildMemberAdd",
      () => runAfterGuards(member.guild.id, () => onGuildMemberAdd(client2, member))
    ));
    client2.on(Events.GuildMemberRemove, (member) => runSafely(
      "GuildMemberRemove",
      () => runAfterGuards(member.guild.id, () => onGuildMemberRemove(client2, member))
    ));
    client2.on(Events.VoiceStateUpdate, (oldState, newState) => runSafely(
      "VoiceStateUpdate",
      () => runAfterGuards(newState.guild.id, () => onVoiceStateUpdate(client2, oldState, newState))
    ));
    client2.on(Events.PresenceUpdate, (oldPresence, newPresence) => runSafely("PresenceUpdate", async () => {
      const guildId = newPresence?.guild?.id || oldPresence?.guild?.id;
      if (guildId) await runAfterGuards(guildId, () => handlePresenceUpdate(oldPresence, newPresence));
      else await handlePresenceUpdate(oldPresence, newPresence);
    }));
    client2.on(Events.GuildCreate, (guild) => runSafely(
      "GuildCreate",
      () => runAfterGuards(guild.id, () => onGuildCreate(client2, guild))
    ));
    client2.on(Events.Error, (error) => {
      logger.error("Discord client error event", error, "Discord");
    });
    registerAuditEvents(client2);
    logger.success("T\xFCm olay dinleyicileri (events) ve audit mod\xFCl\xFC ba\u015Far\u0131yla ba\u011Fland\u0131.", "EventHandler");
  } catch (error) {
    logger.error("Olay dinleyicileri ba\u011Flan\u0131rken hata olu\u015Ftu", error, "EventHandler");
  }
}

// src/index.ts
var client = new Client7({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMembers,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
    GatewayIntentBits.GuildPresences,
    GatewayIntentBits.GuildMessageReactions,
    GatewayIntentBits.GuildVoiceStates,
    GatewayIntentBits.GuildModeration
  ],
  partials: [
    Partials.Message,
    Partials.Channel,
    Partials.Reaction,
    Partials.User,
    Partials.GuildMember,
    Partials.GuildScheduledEvent
  ]
});
client.commands = new Collection2();
client.cooldowns = new Collection2();
async function startBot() {
  console.log(`
  \u2566  \u2566\u2554\u2550\u2557\u2554\u2550\u2557\u2554\u2550\u2557
  \u255A\u2557\u2554\u255D\u2551\u2563 \u2551 \u2566\u2560\u2550\u2563
   \u255A\u255D \u255A\u2550\u255D\u255A\u2550\u255D\u2569 \u2569  ${config.name} Bot ${config.version} (Prefix: ${config.prefix} | Slash: /yardim)
  `);
  logger.info("Vega Bot ba\u015Flat\u0131l\u0131yor...", "Main");
  logger.info(
    `Prefix sistemi aktif ('${config.prefix}'). T\xFCm komutlar ${config.prefix}komut bi\xE7iminde, yaln\u0131zca /yardim slash olarak \xE7al\u0131\u015F\u0131r.`,
    "Main"
  );
  initDatabase();
  loadCommands(client);
  loadEvents(client);
  const token = config.token;
  if (!token) {
    logger.warn("DISCORD_TOKEN bulunamad\u0131! L\xFCtfen .env dosyan\u0131z\u0131 yap\u0131land\u0131r\u0131n.", "Auth");
    logger.info("Bot yap\u0131land\u0131rmas\u0131 tamamland\u0131 ve haz\u0131r.", "Main");
    return;
  }
  try {
    await client.login(token);
  } catch (error) {
    logger.error("Discord API giri\u015F hatas\u0131:", error, "Auth");
  }
}
startBot();
function shutdown(signal) {
  logger.info(`${signal} al\u0131nd\u0131; presence zamanlay\u0131c\u0131s\u0131 kapat\u0131l\u0131yor.`, "Main");
  stopPresenceRotator(client);
  client.destroy();
}
process.once("SIGINT", shutdown);
process.once("SIGTERM", shutdown);
process.on("unhandledRejection", (reason, promise) => {
  logger.error("\u0130\u015Flenmemi\u015F Promise Reddi:", reason, "Process");
});
process.on("uncaughtException", (error) => {
  logger.error("\u0130\u015Flenmemi\u015F \u0130stisna:", error, "Process");
});
export {
  client
};
